// Harness: the loop -- keep feeding real tool results back into the model.
/**
 * s01_agent_loop.ts - The Agent Loop
 *
 * This file teaches the smallest useful coding-agent pattern:
 *
 *     user message
 *       -> model reply
 *       -> if tool_use: execute tools
 *       -> write tool_result back to messages
 *       -> continue
 *
 * It intentionally keeps the loop small, but still makes the loop state explicit
 * so later chapters can grow from the same structure.
 */

import Anthropic from "@anthropic-ai/sdk";
import * as readline from "readline";
import { execSync } from "child_process";
import "dotenv/config";

if (process.env.ANTHROPIC_BASE_URL) {
  delete process.env.ANTHROPIC_AUTH_TOKEN;
}

const client = new Anthropic({
  baseURL: process.env.ANTHROPIC_BASE_URL,
});
const MODEL = process.env.MODEL_ID!;

const SYSTEM =
  `You are a coding agent at ${process.cwd()}. ` +
  "Use bash to inspect and change the workspace. Act first, then report clearly.";

const TOOLS: Anthropic.Tool[] = [
  {
    name: "bash",
    description: "Run a shell command in the current workspace.",
    input_schema: {
      type: "object",
      properties: { command: { type: "string" } },
      required: ["command"],
    },
  },
];

// The minimal loop state: history, loop count, and why we continue.
interface LoopState {
  messages: Anthropic.MessageParam[];
  turnCount: number;
  transitionReason: string | null;
}

function runBash(command: string): string {
  const dangerous = ["rm -rf /", "sudo", "shutdown", "reboot", "> /dev/"];
  if (dangerous.some((item) => command.includes(item))) {
    return "Error: Dangerous command blocked";
  }
  try {
    const output = execSync(command, {
      cwd: process.cwd(),
      timeout: 120000,
      encoding: "utf-8",
      stdio: ["pipe", "pipe", "pipe"],
    });
    return output.trim().slice(0, 50000) || "(no output)";
  } catch (e: any) {
    if (e.signal === "SIGTERM") return "Error: Timeout (120s)";
    const out = ((e.stdout || "") + (e.stderr || "")).trim();
    return out.slice(0, 50000) || `Error: ${e.message}`;
  }
}

function extractText(
  content: Anthropic.ContentBlock[] | string | null
): string {
  if (!Array.isArray(content)) return "";
  return content
    .filter((b): b is Anthropic.TextBlock => b.type === "text")
    .map((b) => b.text)
    .join("\n")
    .trim();
}

function executeToolCalls(
  responseContent: Anthropic.ContentBlock[]
): Anthropic.ToolResultBlockParam[] {
  const results: Anthropic.ToolResultBlockParam[] = [];
  for (const block of responseContent) {
    if (block.type !== "tool_use") continue;
    const command = (block.input as { command: string }).command;
    process.stdout.write(`\x1b[33m$ ${command}\x1b[0m\n`);
    const output = runBash(command);
    console.log(output.slice(0, 200));
    results.push({
      type: "tool_result",
      tool_use_id: block.id,
      content: output,
    });
  }
  return results;
}

async function agentLoop(state: LoopState): Promise<void> {
  while (true) {
    const response = await client.messages.create({
      model: MODEL,
      system: SYSTEM,
      messages: state.messages,
      tools: TOOLS,
      max_tokens: 8000,
    });
    state.messages.push({ role: "assistant", content: response.content });

    if (response.stop_reason !== "tool_use") break;

    const results = executeToolCalls(response.content);
    if (results.length === 0) break;

    state.messages.push({ role: "user", content: results });
    state.turnCount += 1;
    state.transitionReason = "tool_result";
  }
}

async function main() {
  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
    prompt: "\x1b[36ms01 >> \x1b[0m",
  });

  const history: Anthropic.MessageParam[] = [];

  rl.prompt();
  rl.on("line", async (query) => {
    rl.pause();
    if (!query.trim() || ["q", "exit"].includes(query.trim().toLowerCase())) {
      rl.close();
      return;
    }

    history.push({ role: "user", content: query });
    const state: LoopState = { messages: history, turnCount: 1, transitionReason: null };
    await agentLoop(state);

    const lastMsg = history[history.length - 1];
    const finalText = extractText(lastMsg.content as Anthropic.ContentBlock[]);
    if (finalText) console.log(finalText);
    console.log();

    rl.resume();
    rl.prompt();
  });
  rl.on("close", () => process.exit(0));
}

main().catch(console.error);

// Harness: tool dispatch -- expanding what the model can reach.
/**
 * s02_tool_use.ts - Tool dispatch + message normalization
 *
 * The agent loop from s01 didn't change. We added tools to the dispatch map,
 * and a normalizeMessages() function that cleans up the message list before
 * each API call.
 *
 * Key insight: "The loop didn't change at all. I just added tools."
 */

import Anthropic from "@anthropic-ai/sdk";
import * as readline from "readline";
import { execSync } from "child_process";
import * as fs from "fs";
import * as path from "path";
import "dotenv/config";

if (process.env.ANTHROPIC_BASE_URL) {
  delete process.env.ANTHROPIC_AUTH_TOKEN;
}

const WORKDIR = process.cwd();
const client = new Anthropic({ baseURL: process.env.ANTHROPIC_BASE_URL });
const MODEL = process.env.MODEL_ID!;

const SYSTEM = `You are a coding agent at ${WORKDIR}. Use tools to solve tasks. Act, don't explain.`;

function safePath(p: string): string {
  const resolved = path.resolve(WORKDIR, p);
  if (!resolved.startsWith(WORKDIR + path.sep) && resolved !== WORKDIR) {
    throw new Error(`Path escapes workspace: ${p}`);
  }
  return resolved;
}

function runBash(command: string): string {
  const dangerous = ["rm -rf /", "sudo", "shutdown", "reboot", "> /dev/"];
  if (dangerous.some((d) => command.includes(d))) return "Error: Dangerous command blocked";
  try {
    const out = execSync(command, { cwd: WORKDIR, timeout: 120000, encoding: "utf-8", stdio: ["pipe","pipe","pipe"] });
    return out.trim().slice(0, 50000) || "(no output)";
  } catch (e: any) {
    if (e.signal === "SIGTERM") return "Error: Timeout (120s)";
    return (((e.stdout || "") + (e.stderr || "")).trim()).slice(0, 50000) || `Error: ${e.message}`;
  }
}

function runRead(p: string, limit?: number): string {
  try {
    const fp = safePath(p);
    const lines = fs.readFileSync(fp, "utf-8").split("\n");
    const result = limit && limit < lines.length
      ? [...lines.slice(0, limit), `... (${lines.length - limit} more lines)`]
      : lines;
    return result.join("\n").slice(0, 50000);
  } catch (e: any) { return `Error: ${e.message}`; }
}

function runWrite(p: string, content: string): string {
  try {
    const fp = safePath(p);
    fs.mkdirSync(path.dirname(fp), { recursive: true });
    fs.writeFileSync(fp, content, "utf-8");
    return `Wrote ${content.length} bytes to ${p}`;
  } catch (e: any) { return `Error: ${e.message}`; }
}

function runEdit(p: string, oldText: string, newText: string): string {
  try {
    const fp = safePath(p);
    const content = fs.readFileSync(fp, "utf-8");
    if (!content.includes(oldText)) return `Error: Text not found in ${p}`;
    fs.writeFileSync(fp, content.replace(oldText, newText), "utf-8");
    return `Edited ${p}`;
  } catch (e: any) { return `Error: ${e.message}`; }
}

// -- Concurrency safety classification --
// Read-only tools can safely run in parallel; mutating tools must be serialized.
const CONCURRENCY_SAFE = new Set(["read_file"]);
const CONCURRENCY_UNSAFE = new Set(["write_file", "edit_file"]);

// -- The dispatch map: {tool_name: handler} --
const TOOL_HANDLERS: Record<string, (kw: Record<string, any>) => string> = {
  bash:       (kw) => runBash(kw.command),
  read_file:  (kw) => runRead(kw.path, kw.limit),
  write_file: (kw) => runWrite(kw.path, kw.content),
  edit_file:  (kw) => runEdit(kw.path, kw.old_text, kw.new_text),
};

const TOOLS: Anthropic.Tool[] = [
  { name: "bash", description: "Run a shell command.",
    input_schema: { type: "object", properties: { command: { type: "string" } }, required: ["command"] } },
  { name: "read_file", description: "Read file contents.",
    input_schema: { type: "object", properties: { path: { type: "string" }, limit: { type: "integer" } }, required: ["path"] } },
  { name: "write_file", description: "Write content to file.",
    input_schema: { type: "object", properties: { path: { type: "string" }, content: { type: "string" } }, required: ["path", "content"] } },
  { name: "edit_file", description: "Replace exact text in file.",
    input_schema: { type: "object", properties: { path: { type: "string" }, old_text: { type: "string" }, new_text: { type: "string" } }, required: ["path", "old_text", "new_text"] } },
];

function normalizeMessages(messages: Anthropic.MessageParam[]): Anthropic.MessageParam[] {
  /**
   * Clean up messages before sending to the API.
   *
   * Three jobs:
   * 1. Strip internal metadata fields the API doesn't understand
   * 2. Ensure every tool_use has a matching tool_result (insert placeholder if missing)
   * 3. Merge consecutive same-role messages (API requires strict alternation)
   */
  const cleaned: Anthropic.MessageParam[] = messages.map((msg) => {
    if (typeof msg.content === "string") return { role: msg.role, content: msg.content };
    if (Array.isArray(msg.content)) {
      const filteredContent = msg.content
        .filter((b): b is any => typeof b === "object" && b !== null)
        .map((b) => Object.fromEntries(Object.entries(b).filter(([k]) => !k.startsWith("_"))));
      return { role: msg.role, content: filteredContent as unknown as Anthropic.ContentBlock[] };
    }
    return { role: msg.role, content: msg.content ?? "" };
  });

  // Collect existing tool_result IDs
  const existingResults = new Set<string>();
  for (const msg of cleaned) {
    if (Array.isArray(msg.content)) {
      for (const b of msg.content) {
        if (typeof b === "object" && b !== null && (b as any).type === "tool_result") {
          existingResults.add((b as any).tool_use_id);
        }
      }
    }
  }

  // Find orphaned tool_use blocks and insert placeholder results
  for (const msg of cleaned) {
    if (msg.role !== "assistant" || !Array.isArray(msg.content)) continue;
    for (const b of msg.content) {
      if (typeof b === "object" && b !== null && (b as any).type === "tool_use" && !existingResults.has((b as any).id)) {
        cleaned.push({ role: "user", content: [{ type: "tool_result", tool_use_id: (b as any).id, content: "(cancelled)" } as any] });
      }
    }
  }

  // Merge consecutive same-role messages
  if (!cleaned.length) return cleaned;
  const merged: Anthropic.MessageParam[] = [cleaned[0]];
  for (const msg of cleaned.slice(1)) {
    const prev = merged[merged.length - 1];
    if (msg.role === prev.role) {
      const prevC = Array.isArray(prev.content) ? prev.content : [{ type: "text", text: String(prev.content) }];
      const currC = Array.isArray(msg.content) ? msg.content : [{ type: "text", text: String(msg.content) }];
      prev.content = [...prevC, ...currC] as Anthropic.ContentBlock[];
    } else {
      merged.push(msg);
    }
  }
  return merged;
}

async function agentLoop(messages: Anthropic.MessageParam[]): Promise<void> {
  while (true) {
    const response = await client.messages.create({
      model: MODEL, 
      system: SYSTEM,
      messages: normalizeMessages(messages),
      tools: TOOLS, 
      max_tokens: 8000,
    });
    messages.push({ role: "assistant", content: response.content });
    if (response.stop_reason !== "tool_use") return;
    const results: Anthropic.ToolResultBlockParam[] = [];
    for (const block of response.content) {
      if (block.type === "tool_use") {
        const handler = TOOL_HANDLERS[block.name];
        const output = handler ? handler(block.input as Record<string, any>) : `Unknown tool: ${block.name}`;
        console.log(`> ${block.name}:`);
        console.log(String(output).slice(0, 200));
        results.push({ type: "tool_result", tool_use_id: block.id, content: output });
      }
    }
    messages.push({ role: "user", content: results });
  }
}

async function main() {
  const rl = readline.createInterface({ input: process.stdin, output: process.stdout, prompt: "\x1b[36ms02 >> \x1b[0m" });
  const history: Anthropic.MessageParam[] = [];
  rl.prompt();
  rl.on("line", async (query) => {
    rl.pause();
    if (!query.trim() || ["q", "exit"].includes(query.trim().toLowerCase())) { rl.close(); return; }
    history.push({ role: "user", content: query });
    await agentLoop(history);
    const last = history[history.length - 1];
    if (Array.isArray(last.content)) {
      for (const b of last.content) {
        if (typeof b === "object" && b !== null && (b as any).type === "text") console.log((b as any).text);
      }
    }
    console.log();
    rl.resume(); rl.prompt();
  });
  rl.on("close", () => process.exit(0));
}

main().catch(console.error);

// Harness: planning -- keep the current session plan outside the model's head.
/**
 * s03_todo_write.ts - Session Planning with TodoWrite
 *
 * This chapter is about a lightweight session plan, not a durable task graph.
 * The model can rewrite its current plan, keep one active step in focus, and get
 * nudged if it stops refreshing the plan for too many rounds.
 */

import Anthropic from "@anthropic-ai/sdk";
import * as readline from "readline";
import { execSync } from "child_process";
import * as fs from "fs";
import * as path from "path";
import "dotenv/config";

if (process.env.ANTHROPIC_BASE_URL) {
  delete process.env.ANTHROPIC_AUTH_TOKEN;
}

const WORKDIR = process.cwd();
const client = new Anthropic({ baseURL: process.env.ANTHROPIC_BASE_URL });
const MODEL = process.env.MODEL_ID!;
const PLAN_REMINDER_INTERVAL = 3;

const SYSTEM = `You are a coding agent at ${WORKDIR}.
Use the todo tool for multi-step work.
Keep exactly one step in_progress when a task has multiple steps.
Refresh the plan as work advances. Prefer tools over prose.`;

interface PlanItem {
  content: string;
  status: "pending" | "in_progress" | "completed";
  activeForm: string;
}

interface PlanningState {
  items: PlanItem[];
  roundsSinceUpdate: number;
}

class TodoManager {
  private state: PlanningState = { items: [], roundsSinceUpdate: 0 };

  update(items: Array<Record<string, string>>): string {
    if (items.length > 12) throw new Error("Keep the session plan short (max 12 items)");

    const normalized: PlanItem[] = [];
    let inProgressCount = 0;
    for (let i = 0; i < items.length; i++) {
      const raw = items[i];
      const content = String(raw.content ?? "").trim();
      const status = String(raw.status ?? "pending").toLowerCase() as PlanItem["status"];
      const activeForm = String(raw.activeForm ?? "").trim();

      if (!content) throw new Error(`Item ${i}: content required`);
      if (!["pending", "in_progress", "completed"].includes(status))
        throw new Error(`Item ${i}: invalid status '${status}'`);
      if (status === "in_progress") inProgressCount++;

      normalized.push({ content, status, activeForm });
    }

    if (inProgressCount > 1) throw new Error("Only one plan item can be in_progress");

    this.state.items = normalized;
    this.state.roundsSinceUpdate = 0;
    return this.render();
  }

  noteRoundWithoutUpdate(): void {
    this.state.roundsSinceUpdate++;
  }

  reminder(): string | null {
    if (!this.state.items.length) return null;
    if (this.state.roundsSinceUpdate < PLAN_REMINDER_INTERVAL) return null;
    return "<reminder>Refresh your current plan before continuing.</reminder>";
  }

  render(): string {
    if (!this.state.items.length) return "No session plan yet.";

    const marker: Record<string, string> = { pending: "[ ]", in_progress: "[>]", completed: "[x]" };
    const lines = this.state.items.map((item) => {
      let line = `${marker[item.status]} ${item.content}`;
      if (item.status === "in_progress" && item.activeForm) line += ` (${item.activeForm})`;
      return line;
    });

    const completed = this.state.items.filter((i) => i.status === "completed").length;
    lines.push(`\n(${completed}/${this.state.items.length} completed)`);
    return lines.join("\n");
  }

  resetRounds(): void { this.state.roundsSinceUpdate = 0; }
}

const TODO = new TodoManager();

function safePath(p: string): string {
  const resolved = path.resolve(WORKDIR, p);
  if (!resolved.startsWith(WORKDIR + path.sep) && resolved !== WORKDIR)
    throw new Error(`Path escapes workspace: ${p}`);
  return resolved;
}

function runBash(command: string): string {
  const dangerous = ["rm -rf /", "sudo", "shutdown", "reboot", "> /dev/"];
  if (dangerous.some((d) => command.includes(d))) return "Error: Dangerous command blocked";
  try {
    const out = execSync(command, { cwd: WORKDIR, timeout: 120000, encoding: "utf-8", stdio: ["pipe","pipe","pipe"] });
    return out.trim().slice(0, 50000) || "(no output)";
  } catch (e: any) {
    if (e.signal === "SIGTERM") return "Error: Timeout (120s)";
    return (((e.stdout || "") + (e.stderr || "")).trim()).slice(0, 50000) || `Error: ${e.message}`;
  }
}

function runRead(p: string, limit?: number): string {
  try {
    const lines = fs.readFileSync(safePath(p), "utf-8").split("\n");
    const result = limit && limit < lines.length ? [...lines.slice(0, limit), `... (${lines.length - limit} more lines)`] : lines;
    return result.join("\n").slice(0, 50000);
  } catch (e: any) { return `Error: ${e.message}`; }
}

function runWrite(p: string, content: string): string {
  try {
    const fp = safePath(p);
    fs.mkdirSync(path.dirname(fp), { recursive: true });
    fs.writeFileSync(fp, content, "utf-8");
    return `Wrote ${content.length} bytes to ${p}`;
  } catch (e: any) { return `Error: ${e.message}`; }
}

function runEdit(p: string, oldText: string, newText: string): string {
  try {
    const fp = safePath(p);
    const content = fs.readFileSync(fp, "utf-8");
    if (!content.includes(oldText)) return `Error: Text not found in ${p}`;
    fs.writeFileSync(fp, content.replace(oldText, newText), "utf-8");
    return `Edited ${p}`;
  } catch (e: any) { return `Error: ${e.message}`; }
}

const TOOL_HANDLERS: Record<string, (kw: Record<string, any>) => string> = {
  bash:       (kw) => runBash(kw.command),
  read_file:  (kw) => runRead(kw.path, kw.limit),
  write_file: (kw) => runWrite(kw.path, kw.content),
  edit_file:  (kw) => runEdit(kw.path, kw.old_text, kw.new_text),
  todo:       (kw) => TODO.update(kw.items),
};

const TOOLS: Anthropic.Tool[] = [
  { name: "bash", description: "Run a shell command.",
    input_schema: { type: "object", properties: { command: { type: "string" } }, required: ["command"] } },
  { name: "read_file", description: "Read file contents.",
    input_schema: { type: "object", properties: { path: { type: "string" }, limit: { type: "integer" } }, required: ["path"] } },
  { name: "write_file", description: "Write content to a file.",
    input_schema: { type: "object", properties: { path: { type: "string" }, content: { type: "string" } }, required: ["path", "content"] } },
  { name: "edit_file", description: "Replace exact text in a file once.",
    input_schema: { type: "object", properties: { path: { type: "string" }, old_text: { type: "string" }, new_text: { type: "string" } }, required: ["path", "old_text", "new_text"] } },
  { name: "todo", description: "Rewrite the current session plan for multi-step work.",
    input_schema: { type: "object", properties: {
      items: { type: "array", items: { type: "object", properties: {
        content: { type: "string" },
        status: { type: "string", enum: ["pending", "in_progress", "completed"] },
        activeForm: { type: "string", description: "Optional present-continuous label." },
      }, required: ["content", "status"] } },
    }, required: ["items"] } },
];

function extractText(content: Anthropic.ContentBlock[] | string): string {
  if (!Array.isArray(content)) return "";
  return content
    .filter((b): b is Anthropic.TextBlock => b.type === "text")
    .map((b) => b.text)
    .join("\n")
    .trim();
}

async function agentLoop(messages: Anthropic.MessageParam[]): Promise<void> {
  while (true) {
    const response = await client.messages.create({
      model: MODEL, system: SYSTEM, messages, tools: TOOLS, max_tokens: 8000,
    });
    messages.push({ role: "assistant", content: response.content });

    if (response.stop_reason !== "tool_use") return;

    const results: Anthropic.ToolResultBlockParam[] = [];
    let usedTodo = false;
    for (const block of response.content) {
      if (block.type !== "tool_use") continue;

      const handler = TOOL_HANDLERS[block.name];
      let output: string;
      try {
        output = handler ? handler(block.input as Record<string, any>) : `Unknown tool: ${block.name}`;
      } catch (e: any) {
        output = `Error: ${e.message}`;
      }

      console.log(`> ${block.name}: ${String(output).slice(0, 200)}`);
      results.push({ type: "tool_result", tool_use_id: block.id, content: String(output) });
      if (block.name === "todo") usedTodo = true;
    }

    if (usedTodo) {
      TODO.resetRounds();
    } else {
      TODO.noteRoundWithoutUpdate();
      const reminder = TODO.reminder();
      if (reminder) results.unshift({ type: "tool_result", tool_use_id: "reminder", content: reminder } as any);
    }

    messages.push({ role: "user", content: results });
  }
}

async function main() {
  const rl = readline.createInterface({ input: process.stdin, output: process.stdout, prompt: "\x1b[36ms03 >> \x1b[0m" });
  const history: Anthropic.MessageParam[] = [];
  rl.prompt();
  rl.on("line", async (query) => {
    rl.pause();
    if (!query.trim() || ["q", "exit"].includes(query.trim().toLowerCase())) { rl.close(); return; }
    history.push({ role: "user", content: query });
    await agentLoop(history);
    const last = history[history.length - 1];
    const finalText = extractText(last.content as Anthropic.ContentBlock[]);
    if (finalText) console.log(finalText);
    console.log();
    rl.resume(); rl.prompt();
  });
  rl.on("close", () => process.exit(0));
}

main().catch(console.error);

// Harness: context isolation -- protecting the model's clarity of thought.
/**
 * s04_subagent.ts - Subagents
 *
 * Spawn a child agent with fresh messages=[]. The child works in its own
 * context, sharing the filesystem, then returns only a summary to the parent.
 *
 *     Parent agent                     Subagent
 *     +------------------+             +------------------+
 *     | messages=[...]   |             | messages=[]      |  <- fresh
 *     |                  |  dispatch   |                  |
 *     | tool: task       | ----------> | while tool_use:  |
 *     |   prompt="..."   |            |   call tools     |
 *     |   description="" |            |   append results |
 *     |                  |  summary   |                  |
 *     |   result = "..." | <--------- | return last text |
 *     +------------------+             +------------------+
 *               |
 *     Parent context stays clean.
 *     Subagent context is discarded.
 *
 * Key insight: "Fresh messages=[] gives context isolation. The parent stays clean."
 *
 * Note: Real Claude Code also uses in-process isolation (not OS-level process
 * forking). The child runs in the same process with a fresh message array and
 * isolated tool context -- same pattern as this teaching implementation.
 */

import Anthropic from "@anthropic-ai/sdk";
import * as readline from "readline";
import { execSync } from "child_process";
import * as fs from "fs";
import * as path from "path";
import * as os from "os";
import "dotenv/config";

if (process.env.ANTHROPIC_BASE_URL) {
  delete process.env.ANTHROPIC_AUTH_TOKEN;
}

const WORKDIR = process.cwd();
const client = new Anthropic({ baseURL: process.env.ANTHROPIC_BASE_URL });
const MODEL = process.env.MODEL_ID!;

const SYSTEM = `You are a coding agent at ${WORKDIR}. Use the task tool to delegate exploration or subtasks.`;
const SUBAGENT_SYSTEM = `You are a coding subagent at ${WORKDIR}. Complete the given task, then summarize your findings.`;

/**
 * Parse agent definition from markdown frontmatter.
 *
 * Real Claude Code loads agent definitions from .claude/agents/*.md.
 * Frontmatter fields: name, tools, disallowedTools, skills, hooks,
 * model, effort, permissionMode, maxTurns, memory, isolation, color,
 * background, initialPrompt, mcpServers.
 * 3 sources: built-in, custom (.claude/agents/), plugin-provided.
 */
class AgentTemplate {
  name: string;
  config: Record<string, string> = {};
  systemPrompt: string = "";

  constructor(private filePath: string) {
    this.name = path.basename(filePath, path.extname(filePath));
    this._parse();
  }

  private _parse(): void {
    const text = fs.readFileSync(this.filePath, "utf-8");
    const match = text.match(/^---\s*\n(.*?)\n---\s*\n(.*)/s);
    if (!match) { this.systemPrompt = text; return; }
    for (const line of match[1].split("\n")) {
      const idx = line.indexOf(":");
      if (idx >= 0) this.config[line.slice(0, idx).trim()] = line.slice(idx + 1).trim();
    }
    this.systemPrompt = match[2].trim();
    if (this.config.name) this.name = this.config.name;
  }
}

// -- Tool implementations shared by parent and child --
function safePath(p: string): string {
  const resolved = path.resolve(WORKDIR, p);
  if (!resolved.startsWith(WORKDIR + path.sep) && resolved !== WORKDIR)
    throw new Error(`Path escapes workspace: ${p}`);
  return resolved;
}

function runBash(command: string): string {
  const dangerous = ["rm -rf /", "sudo", "shutdown", "reboot", "> /dev/"];
  if (dangerous.some((d) => command.includes(d))) return "Error: Dangerous command blocked";
  try {
    const out = execSync(command, { cwd: WORKDIR, timeout: 120000, encoding: "utf-8", stdio: ["pipe","pipe","pipe"] });
    return out.trim().slice(0, 50000) || "(no output)";
  } catch (e: any) {
    if (e.signal === "SIGTERM") return "Error: Timeout (120s)";
    return (((e.stdout || "") + (e.stderr || "")).trim()).slice(0, 50000) || `Error: ${e.message}`;
  }
}

function runRead(p: string, limit?: number): string {
  try {
    const lines = fs.readFileSync(safePath(p), "utf-8").split("\n");
    const result = limit && limit < lines.length ? [...lines.slice(0, limit), `... (${lines.length - limit} more)`] : lines;
    return result.join("\n").slice(0, 50000);
  } catch (e: any) { return `Error: ${e.message}`; }
}

function runWrite(p: string, content: string): string {
  try {
    const fp = safePath(p);
    fs.mkdirSync(path.dirname(fp), { recursive: true });
    fs.writeFileSync(fp, content, "utf-8");
    return `Wrote ${content.length} bytes`;
  } catch (e: any) { return `Error: ${e.message}`; }
}

function runEdit(p: string, oldText: string, newText: string): string {
  try {
    const fp = safePath(p);
    const content = fs.readFileSync(fp, "utf-8");
    if (!content.includes(oldText)) return `Error: Text not found in ${p}`;
    fs.writeFileSync(fp, content.replace(oldText, newText), "utf-8");
    return `Edited ${p}`;
  } catch (e: any) { return `Error: ${e.message}`; }
}

const TOOL_HANDLERS: Record<string, (kw: Record<string, any>) => string> = {
  bash:       (kw) => runBash(kw.command),
  read_file:  (kw) => runRead(kw.path, kw.limit),
  write_file: (kw) => runWrite(kw.path, kw.content),
  edit_file:  (kw) => runEdit(kw.path, kw.old_text, kw.new_text),
};

// Child gets all base tools except task (no recursive spawning)
const CHILD_TOOLS: Anthropic.Tool[] = [
  { name: "bash", description: "Run a shell command.",
    input_schema: { type: "object", properties: { command: { type: "string" } }, required: ["command"] } },
  { name: "read_file", description: "Read file contents.",
    input_schema: { type: "object", properties: { path: { type: "string" }, limit: { type: "integer" } }, required: ["path"] } },
  { name: "write_file", description: "Write content to file.",
    input_schema: { type: "object", properties: { path: { type: "string" }, content: { type: "string" } }, required: ["path", "content"] } },
  { name: "edit_file", description: "Replace exact text in file.",
    input_schema: { type: "object", properties: { path: { type: "string" }, old_text: { type: "string" }, new_text: { type: "string" } }, required: ["path", "old_text", "new_text"] } },
];

// -- Subagent: fresh context, filtered tools, summary-only return --
async function runSubagent(prompt: string): Promise<string> {
  const subMessages: Anthropic.MessageParam[] = [{ role: "user", content: prompt }]; // fresh context
  let response!: Anthropic.Message;
  for (let i = 0; i < 30; i++) { // safety limit
    response = await client.messages.create({
      model: MODEL, system: SUBAGENT_SYSTEM, messages: subMessages,
      tools: CHILD_TOOLS, max_tokens: 8000,
    });
    subMessages.push({ role: "assistant", content: response.content });
    if (response.stop_reason !== "tool_use") break;
    const results: Anthropic.ToolResultBlockParam[] = [];
    for (const block of response.content) {
      if (block.type === "tool_use") {
        const handler = TOOL_HANDLERS[block.name];
        const output = handler ? handler(block.input as Record<string, any>) : `Unknown tool: ${block.name}`;
        results.push({ type: "tool_result", tool_use_id: block.id, content: String(output).slice(0, 50000) });
      }
    }
    subMessages.push({ role: "user", content: results });
  }
  // Only the final text returns to the parent -- child context is discarded
  return response.content
    .filter((b): b is Anthropic.TextBlock => b.type === "text")
    .map((b) => b.text)
    .join("") || "(no summary)";
}

// -- Parent tools: base tools + task dispatcher --
const PARENT_TOOLS: Anthropic.Tool[] = [
  ...CHILD_TOOLS,
  { name: "task", description: "Spawn a subagent with fresh context. It shares the filesystem but not conversation history.",
    input_schema: { type: "object", properties: { prompt: { type: "string" }, description: { type: "string", description: "Short description of the task" } }, required: ["prompt"] } },
];

async function agentLoop(messages: Anthropic.MessageParam[]): Promise<void> {
  while (true) {
    const response = await client.messages.create({
      model: MODEL, system: SYSTEM, messages, tools: PARENT_TOOLS, max_tokens: 8000,
    });
    messages.push({ role: "assistant", content: response.content });
    if (response.stop_reason !== "tool_use") return;
    const results: Anthropic.ToolResultBlockParam[] = [];
    for (const block of response.content) {
      if (block.type === "tool_use") {
        let output: string;
        if (block.name === "task") {
          const inp = block.input as { prompt: string; description?: string };
          const desc = inp.description ?? "subtask";
          console.log(`> task (${desc}): ${inp.prompt.slice(0, 80)}`);
          output = await runSubagent(inp.prompt);
        } else {
          const handler = TOOL_HANDLERS[block.name];
          output = handler ? handler(block.input as Record<string, any>) : `Unknown tool: ${block.name}`;
        }
        console.log(`  ${String(output).slice(0, 200)}`);
        results.push({ type: "tool_result", tool_use_id: block.id, content: String(output) });
      }
    }
    messages.push({ role: "user", content: results });
  }
}

async function main() {
  const rl = readline.createInterface({ input: process.stdin, output: process.stdout, prompt: "\x1b[36ms04 >> \x1b[0m" });
  const history: Anthropic.MessageParam[] = [];
  rl.prompt();
  rl.on("line", async (query) => {
    rl.pause();
    if (!query.trim() || ["q", "exit"].includes(query.trim().toLowerCase())) { rl.close(); return; }
    history.push({ role: "user", content: query });
    await agentLoop(history);
    const last = history[history.length - 1];
    if (Array.isArray(last.content)) {
      for (const b of last.content) {
        if (typeof b === "object" && b !== null && (b as any).type === "text") console.log((b as any).text);
      }
    }
    console.log();
    rl.resume(); rl.prompt();
  });
  rl.on("close", () => process.exit(0));
}

main().catch(console.error);

// Harness: on-demand knowledge -- discover skills cheaply, load them only when needed.
/**
 * s05_skill_loading.ts - Skills
 *
 * This chapter teaches a two-layer skill model:
 *
 * 1. Put a cheap skill catalog in the system prompt.
 * 2. Load the full skill body only when the model asks for it.
 *
 * That keeps the prompt small while still giving the model access to reusable,
 * task-specific guidance.
 */

import Anthropic from "@anthropic-ai/sdk";
import * as readline from "readline";
import { execSync } from "child_process";
import * as fs from "fs";
import * as path from "path";
import "dotenv/config";

if (process.env.ANTHROPIC_BASE_URL) {
  delete process.env.ANTHROPIC_AUTH_TOKEN;
}

const WORKDIR = process.cwd();
const client = new Anthropic({ baseURL: process.env.ANTHROPIC_BASE_URL });
const MODEL = process.env.MODEL_ID!;
const SKILLS_DIR = path.join(WORKDIR, "skills");

interface SkillManifest {
  name: string;
  description: string;
  filePath: string;
}

interface SkillDocument {
  manifest: SkillManifest;
  body: string;
}

class SkillRegistry {
  private documents: Map<string, SkillDocument> = new Map();

  constructor(private skillsDir: string) {
    this._loadAll();
  }

  private _loadAll(): void {
    if (!fs.existsSync(this.skillsDir)) return;
    this._findSkillFiles(this.skillsDir).sort().forEach((filePath) => {
      const text = fs.readFileSync(filePath, "utf-8");
      const { meta, body } = this._parseFrontmatter(text);
      const name = meta.name ?? path.basename(path.dirname(filePath));
      const description = meta.description ?? "No description";
      const manifest: SkillManifest = { name, description, filePath };
      this.documents.set(name, { manifest, body: body.trim() });
    });
  }

  private _findSkillFiles(dir: string): string[] {
    const results: string[] = [];
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) results.push(...this._findSkillFiles(full));
      else if (entry.name === "SKILL.md") results.push(full);
    }
    return results;
  }

  private _parseFrontmatter(text: string): { meta: Record<string, string>; body: string } {
    const match = text.match(/^---\n(.*?)\n---\n(.*)/s);
    if (!match) return { meta: {}, body: text };
    const meta: Record<string, string> = {};
    for (const line of match[1].trim().split("\n")) {
      const idx = line.indexOf(":");
      if (idx >= 0) meta[line.slice(0, idx).trim()] = line.slice(idx + 1).trim();
    }
    return { meta, body: match[2] };
  }

  describeAvailable(): string {
    if (!this.documents.size) return "(no skills available)";
    return [...this.documents.keys()]
      .sort()
      .map((name) => `- ${name}: ${this.documents.get(name)!.manifest.description}`)
      .join("\n");
  }

  loadFullText(name: string): string {
    const doc = this.documents.get(name);
    if (!doc) {
      const known = [...this.documents.keys()].sort().join(", ") || "(none)";
      return `Error: Unknown skill '${name}'. Available skills: ${known}`;
    }
    return `<skill name="${doc.manifest.name}">\n${doc.body}\n</skill>`;
  }
}

const SKILL_REGISTRY = new SkillRegistry(SKILLS_DIR);

const SYSTEM = `You are a coding agent at ${WORKDIR}.
Use load_skill when a task needs specialized instructions before you act.

Skills available:
${SKILL_REGISTRY.describeAvailable()}
`;

function safePath(p: string): string {
  const resolved = path.resolve(WORKDIR, p);
  if (!resolved.startsWith(WORKDIR + path.sep) && resolved !== WORKDIR)
    throw new Error(`Path escapes workspace: ${p}`);
  return resolved;
}

function runBash(command: string): string {
  const dangerous = ["rm -rf /", "sudo", "shutdown", "reboot", "> /dev/"];
  if (dangerous.some((d) => command.includes(d))) return "Error: Dangerous command blocked";
  try {
    const out = execSync(command, { cwd: WORKDIR, timeout: 120000, encoding: "utf-8", stdio: ["pipe","pipe","pipe"] });
    return out.trim().slice(0, 50000) || "(no output)";
  } catch (e: any) {
    if (e.signal === "SIGTERM") return "Error: Timeout (120s)";
    return (((e.stdout || "") + (e.stderr || "")).trim()).slice(0, 50000) || `Error: ${e.message}`;
  }
}

function runRead(p: string, limit?: number): string {
  try {
    const lines = fs.readFileSync(safePath(p), "utf-8").split("\n");
    const result = limit && limit < lines.length ? [...lines.slice(0, limit), `... (${lines.length - limit} more lines)`] : lines;
    return result.join("\n").slice(0, 50000);
  } catch (e: any) { return `Error: ${e.message}`; }
}

function runWrite(p: string, content: string): string {
  try {
    const fp = safePath(p);
    fs.mkdirSync(path.dirname(fp), { recursive: true });
    fs.writeFileSync(fp, content, "utf-8");
    return `Wrote ${content.length} bytes to ${p}`;
  } catch (e: any) { return `Error: ${e.message}`; }
}

function runEdit(p: string, oldText: string, newText: string): string {
  try {
    const fp = safePath(p);
    const content = fs.readFileSync(fp, "utf-8");
    if (!content.includes(oldText)) return `Error: Text not found in ${p}`;
    fs.writeFileSync(fp, content.replace(oldText, newText), "utf-8");
    return `Edited ${p}`;
  } catch (e: any) { return `Error: ${e.message}`; }
}

const TOOL_HANDLERS: Record<string, (kw: Record<string, any>) => string> = {
  bash:       (kw) => runBash(kw.command),
  read_file:  (kw) => runRead(kw.path, kw.limit),
  write_file: (kw) => runWrite(kw.path, kw.content),
  edit_file:  (kw) => runEdit(kw.path, kw.old_text, kw.new_text),
  load_skill: (kw) => SKILL_REGISTRY.loadFullText(kw.name),
};

const TOOLS: Anthropic.Tool[] = [
  { name: "bash", description: "Run a shell command.",
    input_schema: { type: "object", properties: { command: { type: "string" } }, required: ["command"] } },
  { name: "read_file", description: "Read file contents.",
    input_schema: { type: "object", properties: { path: { type: "string" }, limit: { type: "integer" } }, required: ["path"] } },
  { name: "write_file", description: "Write content to a file.",
    input_schema: { type: "object", properties: { path: { type: "string" }, content: { type: "string" } }, required: ["path", "content"] } },
  { name: "edit_file", description: "Replace exact text in a file once.",
    input_schema: { type: "object", properties: { path: { type: "string" }, old_text: { type: "string" }, new_text: { type: "string" } }, required: ["path", "old_text", "new_text"] } },
  { name: "load_skill", description: "Load the full body of a named skill into the current context.",
    input_schema: { type: "object", properties: { name: { type: "string" } }, required: ["name"] } },
];

function extractText(content: Anthropic.ContentBlock[] | string): string {
  if (!Array.isArray(content)) return "";
  return content
    .filter((b): b is Anthropic.TextBlock => b.type === "text")
    .map((b) => b.text)
    .join("\n")
    .trim();
}

async function agentLoop(messages: Anthropic.MessageParam[]): Promise<void> {
  while (true) {
    const response = await client.messages.create({
      model: MODEL, system: SYSTEM, messages, tools: TOOLS, max_tokens: 8000,
    });
    messages.push({ role: "assistant", content: response.content });
    if (response.stop_reason !== "tool_use") return;

    const results: Anthropic.ToolResultBlockParam[] = [];
    for (const block of response.content) {
      if (block.type !== "tool_use") continue;
      const handler = TOOL_HANDLERS[block.name];
      let output: string;
      try {
        output = handler ? handler(block.input as Record<string, any>) : `Unknown tool: ${block.name}`;
      } catch (e: any) { output = `Error: ${e.message}`; }
      console.log(`> ${block.name}: ${String(output).slice(0, 200)}`);
      results.push({ type: "tool_result", tool_use_id: block.id, content: String(output) });
    }
    messages.push({ role: "user", content: results });
  }
}

async function main() {
  const rl = readline.createInterface({ input: process.stdin, output: process.stdout, prompt: "\x1b[36ms05 >> \x1b[0m" });
  const history: Anthropic.MessageParam[] = [];
  rl.prompt();
  rl.on("line", async (query) => {
    rl.pause();
    if (!query.trim() || ["q", "exit"].includes(query.trim().toLowerCase())) { rl.close(); return; }
    history.push({ role: "user", content: query });
    await agentLoop(history);
    const last = history[history.length - 1];
    const finalText = extractText(last.content as Anthropic.ContentBlock[]);
    if (finalText) console.log(finalText);
    console.log();
    rl.resume(); rl.prompt();
  });
  rl.on("close", () => process.exit(0));
}

