// Harness: compression -- keep the active context small enough to keep working.
/**
 * s06_context_compact.ts - Context Compact
 *
 * This teaching version keeps the compact model intentionally small:
 *
 * 1. Large tool output is persisted to disk and replaced with a preview marker.
 * 2. Older tool results are micro-compacted into short placeholders.
 * 3. When the whole conversation gets too large, the agent summarizes it and
 *    continues from that summary.
 */

import Anthropic from "@anthropic-ai/sdk";
import * as readline from "readline";
import { execSync } from "child_process";
import * as fs from "fs";
import * as path from "path";
import "dotenv/config";

if (process.env.ANTHROPIC_BASE_URL) {
  delete process.env.ANTHROPIC_AUTH_TOKEN;
}

const WORKDIR = process.cwd();
const client = new Anthropic({ baseURL: process.env.ANTHROPIC_BASE_URL });
const MODEL = process.env.MODEL_ID!;

const SYSTEM =
  `You are a coding agent at ${WORKDIR}. ` +
  "Keep working step by step, and use compact if the conversation gets too long.";

const CONTEXT_LIMIT = 50000;
const KEEP_RECENT_TOOL_RESULTS = 3;
const PERSIST_THRESHOLD = 30000;
const PREVIEW_CHARS = 2000;
const TRANSCRIPT_DIR = path.join(WORKDIR, ".transcripts");
const TOOL_RESULTS_DIR = path.join(WORKDIR, ".task_outputs", "tool-results");

interface CompactState {
  hasCompacted: boolean;
  lastSummary: string;
  recentFiles: string[];
}

function estimateContextSize(messages: Anthropic.MessageParam[]): number {
  return JSON.stringify(messages).length;
}

function trackRecentFile(state: CompactState, p: string): void {
  const idx = state.recentFiles.indexOf(p);
  if (idx >= 0) state.recentFiles.splice(idx, 1);
  state.recentFiles.push(p);
  if (state.recentFiles.length > 5) state.recentFiles = state.recentFiles.slice(-5);
}

function safePath(p: string): string {
  const resolved = path.resolve(WORKDIR, p);
  if (!resolved.startsWith(WORKDIR + path.sep) && resolved !== WORKDIR)
    throw new Error(`Path escapes workspace: ${p}`);
  return resolved;
}

function persistLargeOutput(toolUseId: string, output: string): string {
  if (output.length <= PERSIST_THRESHOLD) return output;
  fs.mkdirSync(TOOL_RESULTS_DIR, { recursive: true });
  const storedPath = path.join(TOOL_RESULTS_DIR, `${toolUseId}.txt`);
  if (!fs.existsSync(storedPath)) fs.writeFileSync(storedPath, output, "utf-8");
  const preview = output.slice(0, PREVIEW_CHARS);
  const relPath = path.relative(WORKDIR, storedPath);
  return `<persisted-output>\nFull output saved to: ${relPath}\nPreview:\n${preview}\n</persisted-output>`;
}

function collectToolResultBlocks(messages: Anthropic.MessageParam[]): Array<[number, number, Record<string, any>]> {
  const blocks: Array<[number, number, Record<string, any>]> = [];
  messages.forEach((msg, mi) => {
    if (msg.role !== "user" || !Array.isArray(msg.content)) return;
    (msg.content as any[]).forEach((b, bi) => {
      if (typeof b === "object" && b !== null && b.type === "tool_result") blocks.push([mi, bi, b]);
    });
  });
  return blocks;
}

function microCompact(messages: Anthropic.MessageParam[]): Anthropic.MessageParam[] {
  const toolResults = collectToolResultBlocks(messages);
  if (toolResults.length <= KEEP_RECENT_TOOL_RESULTS) return messages;
  const toCompact = toolResults.slice(0, -KEEP_RECENT_TOOL_RESULTS);
  for (const [, , block] of toCompact) {
    const content = block.content;
    if (typeof content !== "string" || content.length <= 120) continue;
    block.content = "[Earlier tool result compacted. Re-run the tool if you need full detail.]";
  }
  return messages;
}

function writeTranscript(messages: Anthropic.MessageParam[]): string {
  fs.mkdirSync(TRANSCRIPT_DIR, { recursive: true });
  const filePath = path.join(TRANSCRIPT_DIR, `transcript_${Date.now()}.jsonl`);
  const lines = messages.map((m) => JSON.stringify(m, (_, v) => (typeof v === "bigint" ? String(v) : v)));
  fs.writeFileSync(filePath, lines.join("\n"), "utf-8");
  return filePath;
}

async function summarizeHistory(messages: Anthropic.MessageParam[]): Promise<string> {
  const conversation = JSON.stringify(messages).slice(0, 80000);
  const prompt =
    "Summarize this coding-agent conversation so work can continue.\n" +
    "Preserve:\n1. The current goal\n2. Important findings and decisions\n3. Files read or changed\n4. Remaining work\n5. User constraints and preferences\nBe compact but concrete.\n\n" +
    conversation;
  const response = await client.messages.create({
    model: MODEL,
    messages: [{ role: "user", content: prompt }],
    max_tokens: 2000,
  });
  return (response.content[0] as Anthropic.TextBlock).text.trim();
}

async function compactHistory(
  messages: Anthropic.MessageParam[],
  state: CompactState,
  focus?: string
): Promise<Anthropic.MessageParam[]> {
  const transcriptPath = writeTranscript(messages);
  console.log(`[transcript saved: ${transcriptPath}]`);

  let summary = await summarizeHistory(messages);
  if (focus) summary += `\n\nFocus to preserve next: ${focus}`;
  if (state.recentFiles.length) {
    const recentLines = state.recentFiles.map((p) => `- ${p}`).join("\n");
    summary += `\n\nRecent files to reopen if needed:\n${recentLines}`;
  }

  state.hasCompacted = true;
  state.lastSummary = summary;

  return [{
    role: "user",
    content: `This conversation was compacted so the agent can continue working.\n\n${summary}`,
  }];
}

function runBash(command: string, toolUseId: string): string {
  const dangerous = ["rm -rf /", "sudo", "shutdown", "reboot", "> /dev/"];
  if (dangerous.some((d) => command.includes(d))) return "Error: Dangerous command blocked";
  try {
    const out = execSync(command, { cwd: WORKDIR, timeout: 120000, encoding: "utf-8", stdio: ["pipe","pipe","pipe"] });
    const output = out.trim() || "(no output)";
    return persistLargeOutput(toolUseId, output);
  } catch (e: any) {
    if (e.signal === "SIGTERM") return "Error: Timeout (120s)";
    return (((e.stdout || "") + (e.stderr || "")).trim()).slice(0, 50000) || `Error: ${e.message}`;
  }
}

function runRead(p: string, toolUseId: string, state: CompactState, limit?: number): string {
  try {
    trackRecentFile(state, p);
    const lines = fs.readFileSync(safePath(p), "utf-8").split("\n");
    const result = limit && limit < lines.length ? [...lines.slice(0, limit), `... (${lines.length - limit} more lines)`] : lines;
    return persistLargeOutput(toolUseId, result.join("\n"));
  } catch (e: any) { return `Error: ${e.message}`; }
}

function runWrite(p: string, content: string): string {
  try {
    const fp = safePath(p);
    fs.mkdirSync(path.dirname(fp), { recursive: true });
    fs.writeFileSync(fp, content, "utf-8");
    return `Wrote ${content.length} bytes to ${p}`;
  } catch (e: any) { return `Error: ${e.message}`; }
}

function runEdit(p: string, oldText: string, newText: string): string {
  try {
    const fp = safePath(p);
    const content = fs.readFileSync(fp, "utf-8");
    if (!content.includes(oldText)) return `Error: Text not found in ${p}`;
    fs.writeFileSync(fp, content.replace(oldText, newText), "utf-8");
    return `Edited ${p}`;
  } catch (e: any) { return `Error: ${e.message}`; }
}

const TOOLS: Anthropic.Tool[] = [
  { name: "bash", description: "Run a shell command.",
    input_schema: { type: "object", properties: { command: { type: "string" } }, required: ["command"] } },
  { name: "read_file", description: "Read file contents.",
    input_schema: { type: "object", properties: { path: { type: "string" }, limit: { type: "integer" } }, required: ["path"] } },
  { name: "write_file", description: "Write content to a file.",
    input_schema: { type: "object", properties: { path: { type: "string" }, content: { type: "string" } }, required: ["path", "content"] } },
  { name: "edit_file", description: "Replace exact text in a file once.",
    input_schema: { type: "object", properties: { path: { type: "string" }, old_text: { type: "string" }, new_text: { type: "string" } }, required: ["path", "old_text", "new_text"] } },
  { name: "compact", description: "Summarize earlier conversation so work can continue in a smaller context.",
    input_schema: { type: "object", properties: { focus: { type: "string" } } } },
];

function extractText(content: Anthropic.ContentBlock[] | string): string {
  if (!Array.isArray(content)) return "";
  return content.filter((b): b is Anthropic.TextBlock => b.type === "text").map((b) => b.text).join("\n").trim();
}

function executeTool(block: Anthropic.ToolUseBlock, state: CompactState): string {
  const inp = block.input as Record<string, any>;
  if (block.name === "bash") return runBash(inp.command, block.id);
  if (block.name === "read_file") return runRead(inp.path, block.id, state, inp.limit);
  if (block.name === "write_file") return runWrite(inp.path, inp.content);
  if (block.name === "edit_file") return runEdit(inp.path, inp.old_text, inp.new_text);
  if (block.name === "compact") return "Compacting conversation...";
  return `Unknown tool: ${block.name}`;
}

async function agentLoop(messages: Anthropic.MessageParam[], state: CompactState): Promise<void> {
  while (true) {
    messages.splice(0, messages.length, ...microCompact(messages));

    if (estimateContextSize(messages) > CONTEXT_LIMIT) {
      console.log("[auto compact]");
      messages.splice(0, messages.length, ...(await compactHistory(messages, state)));
    }

    const response = await client.messages.create({
      model: MODEL, system: SYSTEM, messages, tools: TOOLS, max_tokens: 8000,
    });
    messages.push({ role: "assistant", content: response.content });
    if (response.stop_reason !== "tool_use") return;

    const results: Anthropic.ToolResultBlockParam[] = [];
    let manualCompact = false;
    let compactFocus: string | undefined;

    for (const block of response.content) {
      if (block.type !== "tool_use") continue;
      const output = executeTool(block, state);
      if (block.name === "compact") {
        manualCompact = true;
        compactFocus = (block.input as any).focus;
      }
      console.log(`> ${block.name}: ${String(output).slice(0, 200)}`);
      results.push({ type: "tool_result", tool_use_id: block.id, content: String(output) });
    }

    messages.push({ role: "user", content: results });

    if (manualCompact) {
      console.log("[manual compact]");
      messages.splice(0, messages.length, ...(await compactHistory(messages, state, compactFocus)));
    }
  }
}

async function main() {
  const rl = readline.createInterface({ input: process.stdin, output: process.stdout, prompt: "\x1b[36ms06 >> \x1b[0m" });
  const history: Anthropic.MessageParam[] = [];
  const compactState: CompactState = { hasCompacted: false, lastSummary: "", recentFiles: [] };
  rl.prompt();
  rl.on("line", async (query) => {
    rl.pause();
    if (!query.trim() || ["q", "exit"].includes(query.trim().toLowerCase())) { rl.close(); return; }
    history.push({ role: "user", content: query });
    await agentLoop(history, compactState);
    const last = history[history.length - 1];
    const finalText = extractText(last.content as Anthropic.ContentBlock[]);
    if (finalText) console.log(finalText);
    console.log();
    rl.resume(); rl.prompt();
  });
  rl.on("close", () => process.exit(0));
}

main().catch(console.error);

// Harness: safety -- the pipeline between intent and execution.
/**
 * s07_permission_system.ts - Permission System
 *
 * Every tool call passes through a permission pipeline before execution.
 *
 * Teaching pipeline:
 *   1. deny rules
 *   2. mode check
 *   3. allow rules
 *   4. ask user
 *
 * This version intentionally teaches three modes first:
 *   - default
 *   - plan
 *   - auto
 *
 * Key insight: "Safety is a pipeline, not a boolean."
 */

import Anthropic from "@anthropic-ai/sdk";
import * as readline from "readline";
import { execSync } from "child_process";
import * as fs from "fs";
import * as path from "path";
import { minimatch } from "minimatch";
import "dotenv/config";

if (process.env.ANTHROPIC_BASE_URL) {
  delete process.env.ANTHROPIC_AUTH_TOKEN;
}

const WORKDIR = process.cwd();
const client = new Anthropic({ baseURL: process.env.ANTHROPIC_BASE_URL });
const MODEL = process.env.MODEL_ID!;

// -- Permission modes --
const MODES = ["default", "plan", "auto"] as const;
type Mode = typeof MODES[number];

const READ_ONLY_TOOLS = new Set(["read_file", "bash_readonly"]);
const WRITE_TOOLS = new Set(["write_file", "edit_file", "bash"]);

// -- Bash security validation --
/**
 * Validate bash commands for obviously dangerous patterns.
 *
 * The teaching version deliberately keeps this small and easy to read.
 * First catch a few high-risk patterns, then let the permission pipeline
 * decide whether to deny or ask the user.
 */
class BashSecurityValidator {
  private static VALIDATORS: Array<[string, RegExp]> = [
    ["shell_metachar", /[;&|`$]/],
    ["sudo", /\bsudo\b/],
    ["rm_rf", /\brm\s+(-[a-zA-Z]*)?r/],
    ["cmd_substitution", /\$\(/],
    ["ifs_injection", /\bIFS\s*=/],
  ];

  validate(command: string): Array<[string, string]> {
    const failures: Array<[string, string]> = [];
    for (const [name, pattern] of BashSecurityValidator.VALIDATORS) {
      if (pattern.test(command)) failures.push([name, pattern.source]);
    }
    return failures;
  }

  isSafe(command: string): boolean {
    return this.validate(command).length === 0;
  }

  describeFailures(command: string): string {
    const failures = this.validate(command);
    if (!failures.length) return "No issues detected";
    return "Security flags: " + failures.map(([n, p]) => `${n} (pattern: ${p})`).join(", ");
  }
}

// -- Workspace trust --
function isWorkspaceTrusted(workspace?: string): boolean {
  const ws = workspace ?? WORKDIR;
  const trustMarker = path.join(ws, ".claude", ".claude_trusted");
  return fs.existsSync(trustMarker);
}

const bashValidator = new BashSecurityValidator();

// -- Permission rules --
interface PermissionRule {
  tool?: string;
  path?: string;
  content?: string;
  behavior: "allow" | "deny" | "ask";
}

const DEFAULT_RULES: PermissionRule[] = [
  { tool: "bash", content: "rm -rf /", behavior: "deny" },
  { tool: "bash", content: "sudo *", behavior: "deny" },
  { tool: "read_file", path: "*", behavior: "allow" },
];

interface PermissionDecision {
  behavior: "allow" | "deny" | "ask";
  reason: string;
}

class PermissionManager {
  mode: Mode;
  rules: PermissionRule[];
  consecutiveDenials = 0;
  maxConsecutiveDenials = 3;

  constructor(mode: Mode = "default", rules?: PermissionRule[]) {
    if (!MODES.includes(mode)) throw new Error(`Unknown mode: ${mode}. Choose from ${MODES}`);
    this.mode = mode;
    this.rules = rules ?? [...DEFAULT_RULES];
  }

  check(toolName: string, toolInput: Record<string, any>): PermissionDecision {
    // Step 0: Bash security validation
    if (toolName === "bash") {
      const command = toolInput.command ?? "";
      const failures = bashValidator.validate(command);
      if (failures.length) {
        const severe = new Set(["sudo", "rm_rf"]);
        const severeHits = failures.filter(([n]) => severe.has(n));
        const desc = bashValidator.describeFailures(command);
        if (severeHits.length) return { behavior: "deny", reason: `Bash validator: ${desc}` };
        return { behavior: "ask", reason: `Bash validator flagged: ${desc}` };
      }
    }

    // Step 1: Deny rules
    for (const rule of this.rules) {
      if (rule.behavior !== "deny") continue;
      if (this._matches(rule, toolName, toolInput)) return { behavior: "deny", reason: `Blocked by deny rule: ${JSON.stringify(rule)}` };
    }

    // Step 2: Mode-based decisions
    if (this.mode === "plan") {
      if (WRITE_TOOLS.has(toolName)) return { behavior: "deny", reason: "Plan mode: write operations are blocked" };
      return { behavior: "allow", reason: "Plan mode: read-only allowed" };
    }

    if (this.mode === "auto") {
      if (READ_ONLY_TOOLS.has(toolName) || toolName === "read_file")
        return { behavior: "allow", reason: "Auto mode: read-only tool auto-approved" };
    }

    // Step 3: Allow rules
    for (const rule of this.rules) {
      if (rule.behavior !== "allow") continue;
      if (this._matches(rule, toolName, toolInput)) {
        this.consecutiveDenials = 0;
        return { behavior: "allow", reason: `Matched allow rule: ${JSON.stringify(rule)}` };
      }
    }

    // Step 4: Ask user
    return { behavior: "ask", reason: `No rule matched for ${toolName}, asking user` };
  }

  askUser(toolName: string, toolInput: Record<string, any>, rl: readline.Interface): Promise<boolean> {
    return new Promise((resolve) => {
      const preview = JSON.stringify(toolInput).slice(0, 200);
      process.stdout.write(`\n  [Permission] ${toolName}: ${preview}\n  Allow? (y/n/always): `);
      rl.once("line", (answer) => {
        const a = answer.trim().toLowerCase();
        if (a === "always") {
          this.rules.push({ tool: toolName, path: "*", behavior: "allow" });
          this.consecutiveDenials = 0;
          resolve(true);
        } else if (a === "y" || a === "yes") {
          this.consecutiveDenials = 0;
          resolve(true);
        } else {
          this.consecutiveDenials++;
          if (this.consecutiveDenials >= this.maxConsecutiveDenials) {
            console.log(`  [${this.consecutiveDenials} consecutive denials -- consider switching to plan mode]`);
          }
          resolve(false);
        }
      });
    });
  }

  private _matches(rule: PermissionRule, toolName: string, toolInput: Record<string, any>): boolean {
    if (rule.tool && rule.tool !== "*" && rule.tool !== toolName) return false;
    if (rule.path && rule.path !== "*") {
      const p = toolInput.path ?? "";
      if (!minimatch(p, rule.path)) return false;
    }
    if (rule.content) {
      const command = toolInput.command ?? "";
      if (!minimatch(command, rule.content)) return false;
    }
    return true;
  }
}

// -- Tool implementations --
function safePath(p: string): string {
  const resolved = path.resolve(WORKDIR, p);
  if (!resolved.startsWith(WORKDIR + path.sep) && resolved !== WORKDIR)
    throw new Error(`Path escapes workspace: ${p}`);
  return resolved;
}

function runBash(command: string): string {
  try {
    const out = execSync(command, { cwd: WORKDIR, timeout: 120000, encoding: "utf-8", stdio: ["pipe","pipe","pipe"] });
    return out.trim().slice(0, 50000) || "(no output)";
  } catch (e: any) {
    if (e.signal === "SIGTERM") return "Error: Timeout (120s)";
    return (((e.stdout || "") + (e.stderr || "")).trim()).slice(0, 50000) || `Error: ${e.message}`;
  }
}

function runRead(p: string, limit?: number): string {
  try {
    const lines = fs.readFileSync(safePath(p), "utf-8").split("\n");
    const result = limit && limit < lines.length ? [...lines.slice(0, limit), `... (${lines.length - limit} more)`] : lines;
    return result.join("\n").slice(0, 50000);
  } catch (e: any) { return `Error: ${e.message}`; }
}

function runWrite(p: string, content: string): string {
  try {
    const fp = safePath(p);
    fs.mkdirSync(path.dirname(fp), { recursive: true });
    fs.writeFileSync(fp, content, "utf-8");
    return `Wrote ${content.length} bytes`;
  } catch (e: any) { return `Error: ${e.message}`; }
}

function runEdit(p: string, oldText: string, newText: string): string {
  try {
    const fp = safePath(p);
    const content = fs.readFileSync(fp, "utf-8");
    if (!content.includes(oldText)) return `Error: Text not found in ${p}`;
    fs.writeFileSync(fp, content.replace(oldText, newText), "utf-8");
    return `Edited ${p}`;
  } catch (e: any) { return `Error: ${e.message}`; }
}

const TOOL_HANDLERS: Record<string, (kw: Record<string, any>) => string> = {
  bash:       (kw) => runBash(kw.command),
  read_file:  (kw) => runRead(kw.path, kw.limit),
  write_file: (kw) => runWrite(kw.path, kw.content),
  edit_file:  (kw) => runEdit(kw.path, kw.old_text, kw.new_text),
};

const TOOLS: Anthropic.Tool[] = [
  { name: "bash", description: "Run a shell command.",
    input_schema: { type: "object", properties: { command: { type: "string" } }, required: ["command"] } },
  { name: "read_file", description: "Read file contents.",
    input_schema: { type: "object", properties: { path: { type: "string" }, limit: { type: "integer" } }, required: ["path"] } },
  { name: "write_file", description: "Write content to file.",
    input_schema: { type: "object", properties: { path: { type: "string" }, content: { type: "string" } }, required: ["path", "content"] } },
  { name: "edit_file", description: "Replace exact text in file.",
    input_schema: { type: "object", properties: { path: { type: "string" }, old_text: { type: "string" }, new_text: { type: "string" } }, required: ["path", "old_text", "new_text"] } },
];

const SYSTEM = `You are a coding agent at ${WORKDIR}. Use tools to solve tasks.
The user controls permissions. Some tool calls may be denied.`;

async function agentLoop(messages: Anthropic.MessageParam[], perms: PermissionManager, rl: readline.Interface): Promise<void> {
  while (true) {
    const response = await client.messages.create({
      model: MODEL, system: SYSTEM, messages, tools: TOOLS, max_tokens: 8000,
    });
    messages.push({ role: "assistant", content: response.content });
    if (response.stop_reason !== "tool_use") return;

    const results: Anthropic.ToolResultBlockParam[] = [];
    for (const block of response.content) {
      if (block.type !== "tool_use") continue;
      const inp = block.input as Record<string, any>;
      const decision = perms.check(block.name, inp);

      let output: string;
      if (decision.behavior === "deny") {
        output = `Permission denied: ${decision.reason}`;
        console.log(`  [DENIED] ${block.name}: ${decision.reason}`);
      } else if (decision.behavior === "ask") {
        const approved = await perms.askUser(block.name, inp, rl);
        if (approved) {
          const handler = TOOL_HANDLERS[block.name];
          output = handler ? handler(inp) : `Unknown: ${block.name}`;
          console.log(`> ${block.name}: ${String(output).slice(0, 200)}`);
        } else {
          output = `Permission denied by user for ${block.name}`;
          console.log(`  [USER DENIED] ${block.name}`);
        }
      } else {
        const handler = TOOL_HANDLERS[block.name];
        output = handler ? handler(inp) : `Unknown: ${block.name}`;
        console.log(`> ${block.name}: ${String(output).slice(0, 200)}`);
      }

      results.push({ type: "tool_result", tool_use_id: block.id, content: String(output) });
    }
    messages.push({ role: "user", content: results });
  }
}

async function main() {
  const rl = readline.createInterface({ input: process.stdin, output: process.stdout });

  console.log("Permission modes: default, plan, auto");
  const modeInput = await new Promise<string>((r) => rl.question("Mode (default): ", r));
  const mode = (MODES.includes(modeInput.trim().toLowerCase() as Mode) ? modeInput.trim().toLowerCase() : "default") as Mode;
  const perms = new PermissionManager(mode);
  console.log(`[Permission mode: ${mode}]`);

  const history: Anthropic.MessageParam[] = [];
  rl.setPrompt("\x1b[36ms07 >> \x1b[0m");
  rl.prompt();
  rl.on("line", async (query) => {
    rl.pause();
    if (!query.trim() || ["q", "exit"].includes(query.trim().toLowerCase())) { rl.close(); return; }

    if (query.startsWith("/mode")) {
      const parts = query.split(/\s+/);
      if (parts.length === 2 && MODES.includes(parts[1] as Mode)) {
        perms.mode = parts[1] as Mode;
        console.log(`[Switched to ${parts[1]} mode]`);
      } else {
        console.log(`Usage: /mode <${MODES.join("|")}>`);
      }
      rl.resume(); rl.prompt(); return;
    }

    if (query.trim() === "/rules") {
      perms.rules.forEach((r, i) => console.log(`  ${i}: ${JSON.stringify(r)}`));
      rl.resume(); rl.prompt(); return;
    }

    history.push({ role: "user", content: query });
    await agentLoop(history, perms, rl);
    const last = history[history.length - 1];
    if (Array.isArray(last.content)) {
      for (const b of last.content) {
        if (typeof b === "object" && b !== null && (b as any).type === "text") console.log((b as any).text);
      }
    }
    console.log();
    rl.resume(); rl.prompt();
  });
  rl.on("close", () => process.exit(0));
}

main().catch(console.error);

// Harness: extensibility -- injecting behavior without touching the loop.
/**
 * s08_hook_system.ts - Hook System
 *
 * Hooks are extension points around the main loop.
 * They let readers add behavior without rewriting the loop itself.
 *
 * Teaching version:
 *   - SessionStart
 *   - PreToolUse
 *   - PostToolUse
 *
 * Teaching exit-code contract:
 *   - 0 -> continue
 *   - 1 -> block
 *   - 2 -> inject a message
 *
 * Key insight: "Extend the agent without touching the loop."
 */

import Anthropic from "@anthropic-ai/sdk";
import * as readline from "readline";
import { execSync, spawnSync } from "child_process";
import * as fs from "fs";
import * as path from "path";
import "dotenv/config";

if (process.env.ANTHROPIC_BASE_URL) {
  delete process.env.ANTHROPIC_AUTH_TOKEN;
}

const WORKDIR = process.cwd();
const client = new Anthropic({ baseURL: process.env.ANTHROPIC_BASE_URL });
const MODEL = process.env.MODEL_ID!;

// The teaching version keeps only the three clearest events. More complete
// systems can grow the event surface later.
const HOOK_EVENTS = ["PreToolUse", "PostToolUse", "SessionStart"] as const;
type HookEvent = typeof HOOK_EVENTS[number];
const HOOK_TIMEOUT = 30; // seconds

// Workspace trust marker. Hooks only run if this file exists (or SDK mode).
const TRUST_MARKER = path.join(WORKDIR, ".claude", ".claude_trusted");

interface HookDef {
  matcher?: string;
  command?: string;
}

interface HookConfig {
  hooks?: { [event: string]: HookDef[] };
}

interface HookResult {
  blocked: boolean;
  messages: string[];
  blockReason?: string;
  permissionOverride?: string;
}

/**
 * Load and execute hooks from .hooks.json configuration.
 *
 * The hook manager does three simple jobs:
 * - load hook definitions
 * - run matching commands for an event
 * - aggregate block / message results for the caller
 */
class HookManager {
  private hooks: { [K in HookEvent]: HookDef[] } = {
    PreToolUse: [], PostToolUse: [], SessionStart: [],
  };
  private sdkMode: boolean;

  constructor(configPath?: string, sdkMode = false) {
    this.sdkMode = sdkMode;
    const cPath = configPath ?? path.join(WORKDIR, ".hooks.json");
    if (fs.existsSync(cPath)) {
      try {
        const config: HookConfig = JSON.parse(fs.readFileSync(cPath, "utf-8"));
        for (const event of HOOK_EVENTS) {
          this.hooks[event] = config.hooks?.[event] ?? [];
        }
        console.log(`[Hooks loaded from ${cPath}]`);
      } catch (e: any) {
        console.log(`[Hook config error: ${e.message}]`);
      }
    }
  }

  private _checkWorkspaceTrust(): boolean {
    if (this.sdkMode) return true;
    return fs.existsSync(TRUST_MARKER);
  }

  runHooks(event: HookEvent, context: Record<string, any> = {}): HookResult {
    const result: HookResult = { blocked: false, messages: [] };
    if (!this._checkWorkspaceTrust()) return result;

    const hooks = this.hooks[event] ?? [];
    for (const hookDef of hooks) {
      const matcher = hookDef.matcher;
      if (matcher && context) {
        const toolName = context.tool_name ?? "";
        if (matcher !== "*" && matcher !== toolName) continue;
      }

      const command = hookDef.command;
      if (!command) continue;

      const env: Record<string, string> = { ...process.env as any };
      if (context) {
        env.HOOK_EVENT = event;
        env.HOOK_TOOL_NAME = context.tool_name ?? "";
        env.HOOK_TOOL_INPUT = JSON.stringify(context.tool_input ?? {}).slice(0, 10000);
        if (context.tool_output !== undefined) env.HOOK_TOOL_OUTPUT = String(context.tool_output).slice(0, 10000);
      }

      try {
        const r = spawnSync(command, { shell: true, cwd: WORKDIR, env, timeout: HOOK_TIMEOUT * 1000, encoding: "utf-8" });

        if (r.status === 0) {
          const stdout = (r.stdout ?? "").trim();
          if (stdout) console.log(`  [hook:${event}] ${stdout.slice(0, 100)}`);
          try {
            const hookOutput = JSON.parse(stdout);
            if (hookOutput.updatedInput && context) context.tool_input = hookOutput.updatedInput;
            if (hookOutput.additionalContext) result.messages.push(hookOutput.additionalContext);
            if (hookOutput.permissionDecision) result.permissionOverride = hookOutput.permissionDecision;
          } catch { /* stdout was not JSON -- normal for simple hooks */ }
        } else if (r.status === 1) {
          result.blocked = true;
          const reason = (r.stderr ?? "").trim() || "Blocked by hook";
          result.blockReason = reason;
          console.log(`  [hook:${event}] BLOCKED: ${reason.slice(0, 200)}`);
        } else if (r.status === 2) {
          const msg = (r.stderr ?? "").trim();
          if (msg) {
            result.messages.push(msg);
            console.log(`  [hook:${event}] INJECT: ${msg.slice(0, 200)}`);
          }
        }

        if (r.error) throw r.error;
      } catch (e: any) {
        if (e.code === "ETIMEDOUT") console.log(`  [hook:${event}] Timeout (${HOOK_TIMEOUT}s)`);
        else console.log(`  [hook:${event}] Error: ${e.message}`);
      }
    }
    return result;
  }
}

// -- Tool implementations (same as s02) --
function safePath(p: string): string {
  const resolved = path.resolve(WORKDIR, p);
  if (!resolved.startsWith(WORKDIR + path.sep) && resolved !== WORKDIR)
    throw new Error(`Path escapes workspace: ${p}`);
  return resolved;
}

function runBash(command: string): string {
  const dangerous = ["rm -rf /", "sudo", "shutdown", "reboot", "> /dev/"];
  if (dangerous.some((d) => command.includes(d))) return "Error: Dangerous command blocked";
  try {
    const out = execSync(command, { cwd: WORKDIR, timeout: 120000, encoding: "utf-8", stdio: ["pipe","pipe","pipe"] });
    return out.trim().slice(0, 50000) || "(no output)";
  } catch (e: any) {
    if (e.signal === "SIGTERM") return "Error: Timeout (120s)";
    return (((e.stdout || "") + (e.stderr || "")).trim()).slice(0, 50000) || `Error: ${e.message}`;
  }
}

function runRead(p: string, limit?: number): string {
  try {
    const lines = fs.readFileSync(safePath(p), "utf-8").split("\n");
    const result = limit && limit < lines.length ? [...lines.slice(0, limit), `... (${lines.length - limit} more)`] : lines;
    return result.join("\n").slice(0, 50000);
  } catch (e: any) { return `Error: ${e.message}`; }
}

function runWrite(p: string, content: string): string {
  try {
    const fp = safePath(p);
    fs.mkdirSync(path.dirname(fp), { recursive: true });
    fs.writeFileSync(fp, content, "utf-8");
    return `Wrote ${content.length} bytes`;
  } catch (e: any) { return `Error: ${e.message}`; }
}

function runEdit(p: string, oldText: string, newText: string): string {
  try {
    const fp = safePath(p);
    const content = fs.readFileSync(fp, "utf-8");
    if (!content.includes(oldText)) return `Error: Text not found in ${p}`;
    fs.writeFileSync(fp, content.replace(oldText, newText), "utf-8");
    return `Edited ${p}`;
  } catch (e: any) { return `Error: ${e.message}`; }
}

const TOOL_HANDLERS: Record<string, (kw: Record<string, any>) => string> = {
  bash:       (kw) => runBash(kw.command),
  read_file:  (kw) => runRead(kw.path, kw.limit),
  write_file: (kw) => runWrite(kw.path, kw.content),
  edit_file:  (kw) => runEdit(kw.path, kw.old_text, kw.new_text),
};

const TOOLS: Anthropic.Tool[] = [
  { name: "bash", description: "Run a shell command.",
    input_schema: { type: "object", properties: { command: { type: "string" } }, required: ["command"] } },
  { name: "read_file", description: "Read file contents.",
    input_schema: { type: "object", properties: { path: { type: "string" }, limit: { type: "integer" } }, required: ["path"] } },
  { name: "write_file", description: "Write content to file.",
    input_schema: { type: "object", properties: { path: { type: "string" }, content: { type: "string" } }, required: ["path", "content"] } },
  { name: "edit_file", description: "Replace exact text in file.",
    input_schema: { type: "object", properties: { path: { type: "string" }, old_text: { type: "string" }, new_text: { type: "string" } }, required: ["path", "old_text", "new_text"] } },
];

const SYSTEM = `You are a coding agent at ${WORKDIR}. Use tools to solve tasks.`;

/**
 * The hook-aware agent loop.
 *
 * The teaching version keeps only the clearest integration points:
 * SessionStart, PreToolUse, execute tool, PostToolUse.
 */
async function agentLoop(messages: Anthropic.MessageParam[], hooks: HookManager): Promise<void> {
  while (true) {
    const response = await client.messages.create({
      model: MODEL, system: SYSTEM, messages, tools: TOOLS, max_tokens: 8000,
    });
    messages.push({ role: "assistant", content: response.content });
    if (response.stop_reason !== "tool_use") return;

    const results: Anthropic.ToolResultBlockParam[] = [];
    for (const block of response.content) {
      if (block.type !== "tool_use") continue;
      const toolInput = { ...(block.input as Record<string, any>) };
      const ctx: { tool_name: string; tool_input: Record<string, any>; tool_output?: string } = { tool_name: block.name, tool_input: toolInput };

      // -- PreToolUse hooks --
      const preResult = hooks.runHooks("PreToolUse", ctx);

      for (const msg of preResult.messages) {
        results.push({ type: "tool_result", tool_use_id: block.id, content: `[Hook message]: ${msg}` });
      }

      if (preResult.blocked) {
        const reason = preResult.blockReason ?? "Blocked by hook";
        const output = `Tool blocked by PreToolUse hook: ${reason}`;
        results.push({ type: "tool_result", tool_use_id: block.id, content: output });
        continue;
      }

      // -- Execute tool --
      const handler = TOOL_HANDLERS[block.name];
      let output: string;
      try {
        output = handler ? handler(toolInput) : `Unknown: ${block.name}`;
      } catch (e: any) { output = `Error: ${e.message}`; }
      console.log(`> ${block.name}: ${String(output).slice(0, 200)}`);

      // -- PostToolUse hooks --
      ctx.tool_output = output;
      const postResult = hooks.runHooks("PostToolUse", ctx);
      for (const msg of postResult.messages) output += `\n[Hook note]: ${msg}`;

      results.push({ type: "tool_result", tool_use_id: block.id, content: String(output) });
    }
    messages.push({ role: "user", content: results });
  }
}

async function main() {
  const hooks = new HookManager();
  hooks.runHooks("SessionStart", { tool_name: "", tool_input: {} });

  const rl = readline.createInterface({ input: process.stdin, output: process.stdout, prompt: "\x1b[36ms08 >> \x1b[0m" });
  const history: Anthropic.MessageParam[] = [];
  rl.prompt();
  rl.on("line", async (query) => {
    rl.pause();
    if (!query.trim() || ["q", "exit"].includes(query.trim().toLowerCase())) { rl.close(); return; }
    history.push({ role: "user", content: query });
    await agentLoop(history, hooks);
    const last = history[history.length - 1];
    if (Array.isArray(last.content)) {
      for (const b of last.content) {
        if (typeof b === "object" && b !== null && (b as any).type === "text") console.log((b as any).text);
      }
    }
    console.log();
    rl.resume(); rl.prompt();
  });
  rl.on("close", () => process.exit(0));
}

main().catch(console.error);

// Harness: persistence -- remembering across the session boundary.
/**
 * s09_memory_system.ts - Memory System
 *
 * This teaching version focuses on one core idea:
 * some information should survive the current conversation, but not everything
 * belongs in memory.
 *
 * Use memory for:
 *   - user preferences
 *   - repeated user feedback
 *   - project facts that are NOT obvious from the current code
 *   - pointers to external resources
 *
 * Do NOT use memory for:
 *   - code structure that can be re-read from the repo
 *   - temporary task state
 *   - secrets
 *
 * Storage layout:
 *   .memory/
 *     MEMORY.md
 *     prefer_tabs.md
 *     review_style.md
 *
 * Key insight: "Memory only stores cross-session information that is still
 * worth recalling later and is not easy to re-derive from the current repo."
 */

import Anthropic from "@anthropic-ai/sdk";
import * as readline from "readline";
import { execSync } from "child_process";
import * as fs from "fs";
import * as path from "path";
import * as os from "os";
import "dotenv/config";

if (process.env.ANTHROPIC_BASE_URL) {
  delete process.env.ANTHROPIC_AUTH_TOKEN;
}

const WORKDIR = process.cwd();
const client = new Anthropic({ baseURL: process.env.ANTHROPIC_BASE_URL });
const MODEL = process.env.MODEL_ID!;

const MEMORY_DIR = path.join(WORKDIR, ".memory");
const MEMORY_INDEX = path.join(MEMORY_DIR, "MEMORY.md");
const MEMORY_TYPES = ["user", "feedback", "project", "reference"] as const;
type MemoryType = typeof MEMORY_TYPES[number];
const MAX_INDEX_LINES = 200;

interface MemoryEntry {
  description: string;
  type: MemoryType;
  content: string;
  file: string;
}

/**
 * Load, build, and save persistent memories across sessions.
 *
 * The teaching version keeps memory explicit:
 * one Markdown file per memory, plus one compact index file.
 */
class MemoryManager {
  memories: Map<string, MemoryEntry> = new Map();

  constructor(private memoryDir: string = MEMORY_DIR) {}

  loadAll(): void {
    this.memories = new Map();
    if (!fs.existsSync(this.memoryDir)) return;

    for (const file of fs.readdirSync(this.memoryDir).sort()) {
      if (!file.endsWith(".md") || file === "MEMORY.md") continue;
      const filePath = path.join(this.memoryDir, file);
      const parsed = this._parseFrontmatter(fs.readFileSync(filePath, "utf-8"));
      if (!parsed) continue;
      const name = parsed.name ?? path.basename(file, ".md");
      this.memories.set(name, {
        description: parsed.description ?? "",
        type: (parsed.type ?? "project") as MemoryType,
        content: parsed.content ?? "",
        file,
      });
    }

    const count = this.memories.size;
    if (count > 0) console.log(`[Memory loaded: ${count} memories from ${this.memoryDir}]`);
  }

  loadMemoryPrompt(): string {
    if (!this.memories.size) return "";
    const sections = ["# Memories (persistent across sessions)", ""];

    for (const memType of MEMORY_TYPES) {
      const typed = [...this.memories.entries()].filter(([, v]) => v.type === memType);
      if (!typed.length) continue;
      sections.push(`## [${memType}]`);
      for (const [name, mem] of typed) {
        sections.push(`### ${name}: ${mem.description}`);
        if (mem.content.trim()) sections.push(mem.content.trim());
        sections.push("");
      }
    }
    return sections.join("\n");
  }

  saveMemory(name: string, description: string, memType: MemoryType, content: string): string {
    if (!MEMORY_TYPES.includes(memType)) return `Error: type must be one of ${MEMORY_TYPES.join(", ")}`;

    const safeName = name.toLowerCase().replace(/[^a-z0-9_-]/g, "_");
    if (!safeName) return "Error: invalid memory name";

    fs.mkdirSync(this.memoryDir, { recursive: true });

    const frontmatter = `---\nname: ${name}\ndescription: ${description}\ntype: ${memType}\n---\n${content}\n`;
    const fileName = `${safeName}.md`;
    const filePath = path.join(this.memoryDir, fileName);
    fs.writeFileSync(filePath, frontmatter, "utf-8");

    this.memories.set(name, { description, type: memType, content, file: fileName });
    this._rebuildIndex();

    return `Saved memory '${name}' [${memType}] to ${path.relative(WORKDIR, filePath)}`;
  }

  private _rebuildIndex(): void {
    const lines = ["# Memory Index", ""];
    for (const [name, mem] of this.memories.entries()) {
      lines.push(`- ${name}: ${mem.description} [${mem.type}]`);
      if (lines.length >= MAX_INDEX_LINES) {
        lines.push(`... (truncated at ${MAX_INDEX_LINES} lines)`);
        break;
      }
    }
    fs.mkdirSync(this.memoryDir, { recursive: true });
    fs.writeFileSync(MEMORY_INDEX, lines.join("\n") + "\n", "utf-8");
  }

  private _parseFrontmatter(text: string): Record<string, string> | null {
    const match = text.match(/^---\s*\n(.*?)\n---\s*\n(.*)/s);
    if (!match) return null;
    const result: Record<string, string> = { content: match[2].trim() };
    for (const line of match[1].split("\n")) {
      const idx = line.indexOf(":");
      if (idx >= 0) result[line.slice(0, idx).trim()] = line.slice(idx + 1).trim();
    }
    return result;
  }
}

/**
 * Auto-consolidation of memories between sessions ("Dream").
 *
 * This is an optional later-stage feature. Its job is to prevent the memory
 * store from growing into a noisy pile by merging, deduplicating, and
 * pruning entries over time.
 */
class DreamConsolidator {
  static COOLDOWN_SECONDS = 86400;       // 24 hours
  static SCAN_THROTTLE_SECONDS = 600;    // 10 minutes
  static MIN_SESSION_COUNT = 5;
  static LOCK_STALE_SECONDS = 3600;

  static PHASES = [
    "Orient: scan MEMORY.md index for structure and categories",
    "Gather: read individual memory files for full content",
    "Consolidate: merge related memories, remove stale entries",
    "Prune: enforce 200-line limit on MEMORY.md index",
  ];

  enabled = true;
  mode = "default";
  lastConsolidationTime = 0;
  lastScanTime = 0;
  sessionCount = 0;

  constructor(private memoryDir: string = MEMORY_DIR) {}

  private get lockFile(): string { return path.join(this.memoryDir, ".dream_lock"); }

  shouldConsolidate(): [boolean, string] {
    const now = Date.now() / 1000;
    if (!this.enabled) return [false, "Gate 1: consolidation is disabled"];
    if (!fs.existsSync(this.memoryDir)) return [false, "Gate 2: memory directory does not exist"];
    const memFiles = fs.readdirSync(this.memoryDir).filter((f) => f.endsWith(".md") && f !== "MEMORY.md");
    if (!memFiles.length) return [false, "Gate 2: no memory files found"];
    if (this.mode === "plan") return [false, "Gate 3: plan mode does not allow consolidation"];
    const timeSinceLast = now - this.lastConsolidationTime;
    if (timeSinceLast < DreamConsolidator.COOLDOWN_SECONDS)
      return [false, `Gate 4: cooldown active, ${Math.round(DreamConsolidator.COOLDOWN_SECONDS - timeSinceLast)}s remaining`];
    const timeSinceScan = now - this.lastScanTime;
    if (timeSinceScan < DreamConsolidator.SCAN_THROTTLE_SECONDS)
      return [false, `Gate 5: scan throttle active, ${Math.round(DreamConsolidator.SCAN_THROTTLE_SECONDS - timeSinceScan)}s remaining`];
    if (this.sessionCount < DreamConsolidator.MIN_SESSION_COUNT)
      return [false, `Gate 6: only ${this.sessionCount} sessions, need ${DreamConsolidator.MIN_SESSION_COUNT}`];
    if (!this._acquireLock()) return [false, "Gate 7: lock held by another process"];
    return [true, "All 7 gates passed"];
  }

  consolidate(): string[] {
    const [canRun, reason] = this.shouldConsolidate();
    if (!canRun) { console.log(`[Dream] Cannot consolidate: ${reason}`); return []; }
    console.log("[Dream] Starting consolidation...");
    this.lastScanTime = Date.now() / 1000;
    const completed: string[] = [];
    DreamConsolidator.PHASES.forEach((phase, i) => {
      console.log(`[Dream] Phase ${i + 1}/4: ${phase}`);
      completed.push(phase);
    });
    this.lastConsolidationTime = Date.now() / 1000;
    this._releaseLock();
    console.log(`[Dream] Consolidation complete: ${completed.length} phases executed`);
    return completed;
  }

  private _acquireLock(): boolean {
    if (fs.existsSync(this.lockFile)) {
      try {
        const lockData = fs.readFileSync(this.lockFile, "utf-8").trim();
        const [pidStr, tsStr] = lockData.split(":");
        const pid = parseInt(pidStr);
        const lockTime = parseFloat(tsStr);
        if ((Date.now() / 1000 - lockTime) > DreamConsolidator.LOCK_STALE_SECONDS) {
          console.log(`[Dream] Removing stale lock from PID ${pid}`);
          fs.unlinkSync(this.lockFile);
        } else {
          try { process.kill(pid, 0); return false; }
          catch { console.log(`[Dream] Removing lock from dead PID ${pid}`); fs.unlinkSync(this.lockFile); }
        }
      } catch { try { fs.unlinkSync(this.lockFile); } catch {} }
    }
    try {
      fs.mkdirSync(this.memoryDir, { recursive: true });
      fs.writeFileSync(this.lockFile, `${process.pid}:${Date.now() / 1000}`, "utf-8");
      return true;
    } catch { return false; }
  }

  private _releaseLock(): void {
    try {
      if (fs.existsSync(this.lockFile)) {
        const lockData = fs.readFileSync(this.lockFile, "utf-8").trim();
        const [pidStr] = lockData.split(":");
        if (parseInt(pidStr) === process.pid) fs.unlinkSync(this.lockFile);
      }
    } catch {}
  }
}

// -- Tool implementations --
function safePath(p: string): string {
  const resolved = path.resolve(WORKDIR, p);
  if (!resolved.startsWith(WORKDIR + path.sep) && resolved !== WORKDIR)
    throw new Error(`Path escapes workspace: ${p}`);
  return resolved;
}

function runBash(command: string): string {
  const dangerous = ["rm -rf /", "sudo", "shutdown", "reboot", "> /dev/"];
  if (dangerous.some((d) => command.includes(d))) return "Error: Dangerous command blocked";
  try {
    const out = execSync(command, { cwd: WORKDIR, timeout: 120000, encoding: "utf-8", stdio: ["pipe","pipe","pipe"] });
    return out.trim().slice(0, 50000) || "(no output)";
  } catch (e: any) {
    if (e.signal === "SIGTERM") return "Error: Timeout (120s)";
    return (((e.stdout || "") + (e.stderr || "")).trim()).slice(0, 50000) || `Error: ${e.message}`;
  }
}

function runRead(p: string, limit?: number): string {
  try {
    const lines = fs.readFileSync(safePath(p), "utf-8").split("\n");
    const result = limit && limit < lines.length ? [...lines.slice(0, limit), `... (${lines.length - limit} more)`] : lines;
    return result.join("\n").slice(0, 50000);
  } catch (e: any) { return `Error: ${e.message}`; }
}

function runWrite(p: string, content: string): string {
  try {
    const fp = safePath(p);
    fs.mkdirSync(path.dirname(fp), { recursive: true });
    fs.writeFileSync(fp, content, "utf-8");
    return `Wrote ${content.length} bytes`;
  } catch (e: any) { return `Error: ${e.message}`; }
}

function runEdit(p: string, oldText: string, newText: string): string {
  try {
    const fp = safePath(p);
    const content = fs.readFileSync(fp, "utf-8");
    if (!content.includes(oldText)) return `Error: Text not found in ${p}`;
    fs.writeFileSync(fp, content.replace(oldText, newText), "utf-8");
    return `Edited ${p}`;
  } catch (e: any) { return `Error: ${e.message}`; }
}

const memoryMgr = new MemoryManager();

const TOOL_HANDLERS: Record<string, (kw: Record<string, any>) => string> = {
  bash:        (kw) => runBash(kw.command),
  read_file:   (kw) => runRead(kw.path, kw.limit),
  write_file:  (kw) => runWrite(kw.path, kw.content),
  edit_file:   (kw) => runEdit(kw.path, kw.old_text, kw.new_text),
  save_memory: (kw) => memoryMgr.saveMemory(kw.name, kw.description, kw.type as MemoryType, kw.content),
};

const TOOLS: Anthropic.Tool[] = [
  { name: "bash", description: "Run a shell command.",
    input_schema: { type: "object", properties: { command: { type: "string" } }, required: ["command"] } },
  { name: "read_file", description: "Read file contents.",
    input_schema: { type: "object", properties: { path: { type: "string" }, limit: { type: "integer" } }, required: ["path"] } },
  { name: "write_file", description: "Write content to file.",
    input_schema: { type: "object", properties: { path: { type: "string" }, content: { type: "string" } }, required: ["path", "content"] } },
  { name: "edit_file", description: "Replace exact text in file.",
    input_schema: { type: "object", properties: { path: { type: "string" }, old_text: { type: "string" }, new_text: { type: "string" } }, required: ["path", "old_text", "new_text"] } },
  { name: "save_memory", description: "Save a persistent memory that survives across sessions.",
    input_schema: { type: "object", properties: {
      name: { type: "string", description: "Short identifier (e.g. prefer_tabs, db_schema)" },
      description: { type: "string", description: "One-line summary of what this memory captures" },
      type: { type: "string", enum: ["user", "feedback", "project", "reference"],
              description: "user=preferences, feedback=corrections, project=non-obvious project conventions or decision reasons, reference=external resource pointers" },
      content: { type: "string", description: "Full memory content (multi-line OK)" },
    }, required: ["name", "description", "type", "content"] } },
];

const MEMORY_GUIDANCE = `
When to save memories:
- User states a preference ("I like tabs", "always use pytest") -> type: user
- User corrects you ("don't do X", "that was wrong because...") -> type: feedback
- You learn a project fact that is not easy to infer from current code alone
  (for example: a rule exists because of compliance, or a legacy module must
  stay untouched for business reasons) -> type: project
- You learn where an external resource lives (ticket board, dashboard, docs URL)
  -> type: reference

When NOT to save:
- Anything easily derivable from code (function signatures, file structure, directory layout)
- Temporary task state (current branch, open PR numbers, current TODOs)
- Secrets or credentials (API keys, passwords)
`;

function buildSystemPrompt(): string {
  const parts = [`You are a coding agent at ${WORKDIR}. Use tools to solve tasks.`];
  const memorySection = memoryMgr.loadMemoryPrompt();
  if (memorySection) parts.push(memorySection);
  parts.push(MEMORY_GUIDANCE);
  return parts.join("\n\n");
}

/**
 * Agent loop with memory-aware system prompt.
 *
 * The system prompt is rebuilt each call so newly saved memories
 * are visible in the next LLM turn within the same session.
 */
async function agentLoop(messages: Anthropic.MessageParam[]): Promise<void> {
  while (true) {
    const system = buildSystemPrompt();
    const response = await client.messages.create({
      model: MODEL, system, messages, tools: TOOLS, max_tokens: 8000,
    });
    messages.push({ role: "assistant", content: response.content });
    if (response.stop_reason !== "tool_use") return;

    const results: Anthropic.ToolResultBlockParam[] = [];
    for (const block of response.content) {
      if (block.type !== "tool_use") continue;
      const handler = TOOL_HANDLERS[block.name];
      let output: string;
      try {
        output = handler ? handler(block.input as Record<string, any>) : `Unknown: ${block.name}`;
      } catch (e: any) { output = `Error: ${e.message}`; }
      console.log(`> ${block.name}: ${String(output).slice(0, 200)}`);
      results.push({ type: "tool_result", tool_use_id: block.id, content: String(output) });
    }
    messages.push({ role: "user", content: results });
  }
}

async function main() {
  memoryMgr.loadAll();
  const memCount = memoryMgr.memories.size;
  if (memCount) console.log(`[${memCount} memories loaded into context]`);
  else console.log("[No existing memories. The agent can create them with save_memory.]");

  const rl = readline.createInterface({ input: process.stdin, output: process.stdout, prompt: "\x1b[36ms09 >> \x1b[0m" });
  const history: Anthropic.MessageParam[] = [];
  rl.prompt();
  rl.on("line", async (query) => {
    rl.pause();
    if (!query.trim() || ["q", "exit"].includes(query.trim().toLowerCase())) { rl.close(); return; }

    if (query.trim() === "/memories") {
      if (memoryMgr.memories.size) {
        for (const [name, mem] of memoryMgr.memories.entries()) {
          console.log(`  [${mem.type}] ${name}: ${mem.description}`);
        }
      } else console.log("  (no memories)");
      rl.resume(); rl.prompt(); return;
    }

    history.push({ role: "user", content: query });
    await agentLoop(history);
    const last = history[history.length - 1];
    if (Array.isArray(last.content)) {
      for (const b of last.content) {
        if (typeof b === "object" && b !== null && (b as any).type === "text") console.log((b as any).text);
      }
    }
    console.log();
    rl.resume(); rl.prompt();
  });
  rl.on("close", () => process.exit(0));
}

main().catch(console.error);

// Harness: assembly -- the system prompt is a pipeline, not a string.
/**
 * s10_system_prompt.ts - System Prompt Construction
 *
 * This chapter teaches one core idea:
 * the system prompt should be assembled from clear sections, not written as one
 * giant hardcoded blob.
 *
 * Teaching pipeline:
 *   1. core instructions
 *   2. tool listing
 *   3. skill metadata
 *   4. memory section
 *   5. CLAUDE.md chain
 *   6. dynamic context
 *
 * Key insight: "Prompt construction is a pipeline with boundaries, not one
 * big string."
 */

import Anthropic from "@anthropic-ai/sdk";
import * as readline from "readline";
import { execSync } from "child_process";
import * as fs from "fs";
import * as path from "path";
import * as os from "os";
import "dotenv/config";

if (process.env.ANTHROPIC_BASE_URL) {
  delete process.env.ANTHROPIC_AUTH_TOKEN;
}

const WORKDIR = process.cwd();
const client = new Anthropic({ baseURL: process.env.ANTHROPIC_BASE_URL });
const MODEL = process.env.MODEL_ID!;

const DYNAMIC_BOUNDARY = "=== DYNAMIC_BOUNDARY ===";

/**
 * Assemble the system prompt from independent sections.
 *
 * The teaching goal here is clarity:
 * each section has one source and one responsibility.
 */
class SystemPromptBuilder {
  private workdir: string;
  private tools: Anthropic.Tool[];
  private skillsDir: string;
  private memoryDir: string;

  constructor(workdir: string = WORKDIR, tools: Anthropic.Tool[] = []) {
    this.workdir = workdir;
    this.tools = tools;
    this.skillsDir = path.join(workdir, "skills");
    this.memoryDir = path.join(workdir, ".memory");
  }

  // -- Section 1: Core instructions --
  private _buildCore(): string {
    return (
      `You are a coding agent operating in ${this.workdir}.\n` +
      "Use the provided tools to explore, read, write, and edit files.\n" +
      "Always verify before assuming. Prefer reading files over guessing."
    );
  }

  // -- Section 2: Tool listings --
  private _buildToolListing(): string {
    if (!this.tools.length) return "";
    const lines = ["# Available tools"];
    for (const tool of this.tools) {
      const props = (tool.input_schema as any)?.properties ?? {};
      const params = Object.keys(props).join(", ");
      lines.push(`- ${tool.name}(${params}): ${tool.description}`);
    }
    return lines.join("\n");
  }

  // -- Section 3: Skill metadata (layer 1 from s05 concept) --
  private _buildSkillListing(): string {
    if (!fs.existsSync(this.skillsDir)) return "";
    const skills: string[] = [];
    for (const entry of fs.readdirSync(this.skillsDir, { withFileTypes: true })) {
      if (!entry.isDirectory()) continue;
      const skillMd = path.join(this.skillsDir, entry.name, "SKILL.md");
      if (!fs.existsSync(skillMd)) continue;
      const text = fs.readFileSync(skillMd, "utf-8");
      const match = text.match(/^---\s*\n(.*?)\n---/s);
      if (!match) continue;
      const meta: Record<string, string> = {};
      for (const line of match[1].split("\n")) {
        const idx = line.indexOf(":");
        if (idx >= 0) meta[line.slice(0, idx).trim()] = line.slice(idx + 1).trim();
      }
      const name = meta.name ?? entry.name;
      const desc = meta.description ?? "";
      skills.push(`- ${name}: ${desc}`);
    }
    if (!skills.length) return "";
    return "# Available skills\n" + skills.join("\n");
  }

  // -- Section 4: Memory content --
  private _buildMemorySection(): string {
    if (!fs.existsSync(this.memoryDir)) return "";
    const memories: string[] = [];
    for (const file of fs.readdirSync(this.memoryDir).sort()) {
      if (!file.endsWith(".md") || file === "MEMORY.md") continue;
      const text = fs.readFileSync(path.join(this.memoryDir, file), "utf-8");
      const match = text.match(/^---\s*\n(.*?)\n---\s*\n(.*)/s);
      if (!match) continue;
      const meta: Record<string, string> = {};
      for (const line of match[1].split("\n")) {
        const idx = line.indexOf(":");
        if (idx >= 0) meta[line.slice(0, idx).trim()] = line.slice(idx + 1).trim();
      }
      const name = meta.name ?? path.basename(file, ".md");
      const memType = meta.type ?? "project";
      const desc = meta.description ?? "";
      const body = match[2].trim();
      memories.push(`[${memType}] ${name}: ${desc}\n${body}`);
    }
    if (!memories.length) return "";
    return "# Memories (persistent)\n\n" + memories.join("\n\n");
  }

  // -- Section 5: CLAUDE.md chain --
  /**
   * Load CLAUDE.md files in priority order (all are included):
   * 1. ~/.claude/CLAUDE.md (user-global instructions)
   * 2. <project-root>/CLAUDE.md (project instructions)
   * 3. <current-subdir>/CLAUDE.md (directory-specific instructions)
   */
  private _buildClaudeMd(): string {
    const sources: Array<[string, string]> = [];

    const userClaude = path.join(os.homedir(), ".claude", "CLAUDE.md");
    if (fs.existsSync(userClaude)) sources.push(["user global (~/.claude/CLAUDE.md)", fs.readFileSync(userClaude, "utf-8")]);

    const projectClaude = path.join(this.workdir, "CLAUDE.md");
    if (fs.existsSync(projectClaude)) sources.push(["project root (CLAUDE.md)", fs.readFileSync(projectClaude, "utf-8")]);

    const cwd = process.cwd();
    if (cwd !== this.workdir) {
      const subdirClaude = path.join(cwd, "CLAUDE.md");
      if (fs.existsSync(subdirClaude))
        sources.push([`subdir (${path.basename(cwd)}/CLAUDE.md)`, fs.readFileSync(subdirClaude, "utf-8")]);
    }

    if (!sources.length) return "";
    const parts = ["# CLAUDE.md instructions"];
    for (const [label, content] of sources) {
      parts.push(`## From ${label}`);
      parts.push(content.trim());
    }
    return parts.join("\n\n");
  }

  // -- Section 6: Dynamic context --
  private _buildDynamicContext(): string {
    const lines = [
      `Current date: ${new Date().toISOString().slice(0, 10)}`,
      `Working directory: ${this.workdir}`,
      `Model: ${MODEL}`,
      `Platform: ${os.platform()}`,
    ];
    return "# Dynamic context\n" + lines.join("\n");
  }

  // -- Assemble all sections --
  build(): string {
    /**
     * Assemble the full system prompt from all sections.
     *
     * Static sections (1-5) are separated from dynamic (6) by
     * the DYNAMIC_BOUNDARY marker. In real CC, the static prefix
     * is cached across turns to save prompt tokens.
     */
    const sections: string[] = [];

    const core = this._buildCore();
    if (core) sections.push(core);

    const tools = this._buildToolListing();
    if (tools) sections.push(tools);

    const skills = this._buildSkillListing();
    if (skills) sections.push(skills);

    const memory = this._buildMemorySection();
    if (memory) sections.push(memory);

    const claudeMd = this._buildClaudeMd();
    if (claudeMd) sections.push(claudeMd);

    sections.push(DYNAMIC_BOUNDARY);

    const dynamic = this._buildDynamicContext();
    if (dynamic) sections.push(dynamic);

    return sections.join("\n\n");
  }
}

/**
 * Build a system-reminder user message for per-turn dynamic content.
 *
 * The teaching version keeps reminders outside the stable system prompt so
 * short-lived context does not get mixed into the long-lived instructions.
 */
function buildSystemReminder(extra?: string): Anthropic.MessageParam | null {
  const parts: string[] = [];
  if (extra) parts.push(extra);
  if (!parts.length) return null;
  const content = `<system-reminder>\n${parts.join("\n")}\n</system-reminder>`;
  return { role: "user", content };
}

// -- Tool implementations --
function safePath(p: string): string {
  const resolved = path.resolve(WORKDIR, p);
  if (!resolved.startsWith(WORKDIR + path.sep) && resolved !== WORKDIR)
    throw new Error(`Path escapes workspace: ${p}`);
  return resolved;
}

function runBash(command: string): string {
  const dangerous = ["rm -rf /", "sudo", "shutdown", "reboot", "> /dev/"];
  if (dangerous.some((d) => command.includes(d))) return "Error: Dangerous command blocked";
  try {
    const out = execSync(command, { cwd: WORKDIR, timeout: 120000, encoding: "utf-8", stdio: ["pipe","pipe","pipe"] });
    return out.trim().slice(0, 50000) || "(no output)";
  } catch (e: any) {
    if (e.signal === "SIGTERM") return "Error: Timeout (120s)";
    return (((e.stdout || "") + (e.stderr || "")).trim()).slice(0, 50000) || `Error: ${e.message}`;
  }
}

function runRead(p: string, limit?: number): string {
  try {
    const lines = fs.readFileSync(safePath(p), "utf-8").split("\n");
    const result = limit && limit < lines.length ? [...lines.slice(0, limit), `... (${lines.length - limit} more)`] : lines;
    return result.join("\n").slice(0, 50000);
  } catch (e: any) { return `Error: ${e.message}`; }
}

function runWrite(p: string, content: string): string {
  try {
    const fp = safePath(p);
    fs.mkdirSync(path.dirname(fp), { recursive: true });
    fs.writeFileSync(fp, content, "utf-8");
    return `Wrote ${content.length} bytes`;
  } catch (e: any) { return `Error: ${e.message}`; }
}

function runEdit(p: string, oldText: string, newText: string): string {
  try {
    const fp = safePath(p);
    const content = fs.readFileSync(fp, "utf-8");
    if (!content.includes(oldText)) return `Error: Text not found in ${p}`;
    fs.writeFileSync(fp, content.replace(oldText, newText), "utf-8");
    return `Edited ${p}`;
  } catch (e: any) { return `Error: ${e.message}`; }
}

const TOOLS: Anthropic.Tool[] = [
  { name: "bash", description: "Run a shell command.",
    input_schema: { type: "object", properties: { command: { type: "string" } }, required: ["command"] } },
  { name: "read_file", description: "Read file contents.",
    input_schema: { type: "object", properties: { path: { type: "string" }, limit: { type: "integer" } }, required: ["path"] } },
  { name: "write_file", description: "Write content to file.",
    input_schema: { type: "object", properties: { path: { type: "string" }, content: { type: "string" } }, required: ["path", "content"] } },
  { name: "edit_file", description: "Replace exact text in file.",
    input_schema: { type: "object", properties: { path: { type: "string" }, old_text: { type: "string" }, new_text: { type: "string" } }, required: ["path", "old_text", "new_text"] } },
];

const TOOL_HANDLERS: Record<string, (kw: Record<string, any>) => string> = {
  bash:       (kw) => runBash(kw.command),
  read_file:  (kw) => runRead(kw.path, kw.limit),
  write_file: (kw) => runWrite(kw.path, kw.content),
  edit_file:  (kw) => runEdit(kw.path, kw.old_text, kw.new_text),
};

const promptBuilder = new SystemPromptBuilder(WORKDIR, TOOLS);

/**
 * Agent loop with assembled system prompt.
 *
 * The system prompt is rebuilt each iteration. In real CC, the static
 * prefix is cached and only the dynamic suffix changes per turn.
 */
async function agentLoop(messages: Anthropic.MessageParam[]): Promise<void> {
  while (true) {
    const system = promptBuilder.build();
    const response = await client.messages.create({
      model: MODEL, system, messages, tools: TOOLS, max_tokens: 8000,
    });
    messages.push({ role: "assistant", content: response.content });
    if (response.stop_reason !== "tool_use") return;

    const results: Anthropic.ToolResultBlockParam[] = [];
    for (const block of response.content) {
      if (block.type !== "tool_use") continue;
      const handler = TOOL_HANDLERS[block.name];
      let output: string;
      try {
        output = handler ? handler(block.input as Record<string, any>) : `Unknown: ${block.name}`;
      } catch (e: any) { output = `Error: ${e.message}`; }
      console.log(`> ${block.name}: ${String(output).slice(0, 200)}`);
      results.push({ type: "tool_result", tool_use_id: block.id, content: String(output) });
    }
    messages.push({ role: "user", content: results });
  }
}

async function main() {
  const fullPrompt = promptBuilder.build();
  const sectionCount = (fullPrompt.match(/\n# /g) || []).length;
  console.log(`[System prompt assembled: ${fullPrompt.length} chars, ~${sectionCount} sections]`);

  const rl = readline.createInterface({ input: process.stdin, output: process.stdout, prompt: "\x1b[36ms10 >> \x1b[0m" });
  const history: Anthropic.MessageParam[] = [];
  rl.prompt();
  rl.on("line", async (query) => {
    rl.pause();
    if (!query.trim() || ["q", "exit"].includes(query.trim().toLowerCase())) { rl.close(); return; }

    if (query.trim() === "/prompt") {
      console.log("--- System Prompt ---");
      console.log(promptBuilder.build());
      console.log("--- End ---");
      rl.resume(); rl.prompt(); return;
    }

    if (query.trim() === "/sections") {
      const prompt = promptBuilder.build();
      for (const line of prompt.split("\n")) {
        if (line.startsWith("# ") || line === DYNAMIC_BOUNDARY) console.log(`  ${line}`);
      }
      rl.resume(); rl.prompt(); return;
    }

    history.push({ role: "user", content: query });
    await agentLoop(history);
    const last = history[history.length - 1];
    if (Array.isArray(last.content)) {
      for (const b of last.content) {
        if (typeof b === "object" && b !== null && (b as any).type === "text") console.log((b as any).text);
      }
    }
    console.log();
    rl.resume(); rl.prompt();
  });
  rl.on("close", () => process.exit(0));
}

main().catch(console.error);

// Harness: resilience -- a robust agent recovers instead of crashing.
/**
 * s11_error_recovery.ts - Error Recovery
 *
 * Teaching demo of three recovery paths:
 *
 * - continue when output is truncated
 * - compact when context grows too large
 * - back off when transport errors are temporary
 *
 *     LLM response
 *          |
 *          v
 *     [Check stop_reason]
 *          |
 *          +-- "max_tokens" ----> [Strategy 1: max_output_tokens recovery]
 *          |                       Inject continuation message.
 *          |                       Retry up to MAX_RECOVERY_ATTEMPTS (3).
 *          |
 *          +-- API error --------> [Check error type]
 *          |                       |
 *          |                       +-- prompt_too_long --> [Strategy 2: compact + retry]
 *          |                       |
 *          |                       +-- connection/rate --> [Strategy 3: backoff retry]
 *          |
 *          +-- "end_turn" ------> [Normal exit]
 */

import Anthropic from "@anthropic-ai/sdk";
import * as readline from "readline";
import { execSync } from "child_process";
import * as fs from "fs";
import * as path from "path";
import "dotenv/config";

if (process.env.ANTHROPIC_BASE_URL) {
  delete process.env.ANTHROPIC_AUTH_TOKEN;
}

const WORKDIR = process.cwd();
const client = new Anthropic({ baseURL: process.env.ANTHROPIC_BASE_URL });
const MODEL = process.env.MODEL_ID!;

const MAX_RECOVERY_ATTEMPTS = 3;
const BACKOFF_BASE_DELAY = 1.0;  // seconds
const BACKOFF_MAX_DELAY = 30.0;  // seconds
const TOKEN_THRESHOLD = 50000;   // chars / 4 ~ tokens for compact trigger

const CONTINUATION_MESSAGE =
  "Output limit hit. Continue directly from where you stopped -- " +
  "no recap, no repetition. Pick up mid-sentence if needed.";

function estimateTokens(messages: Anthropic.MessageParam[]): number {
  return Math.floor(JSON.stringify(messages).length / 4);
}

async function autoCompact(messages: Anthropic.MessageParam[]): Promise<Anthropic.MessageParam[]> {
  const conversationText = JSON.stringify(messages).slice(0, 80000);
  const prompt =
    "Summarize this conversation for continuity. Include:\n" +
    "1) Task overview and success criteria\n" +
    "2) Current state: completed work, files touched\n" +
    "3) Key decisions and failed approaches\n" +
    "4) Remaining next steps\n" +
    "Be concise but preserve critical details.\n\n" +
    conversationText;
  let summary: string;
  try {
    const response = await client.messages.create({
      model: MODEL,
      messages: [{ role: "user", content: prompt }],
      max_tokens: 4000,
    });
    summary = (response.content[0] as Anthropic.TextBlock).text;
  } catch (e: any) {
    summary = `(compact failed: ${e.message}). Previous context lost.`;
  }

  const continuation =
    "This session continues from a previous conversation that was compacted. " +
    `Summary of prior context:\n\n${summary}\n\n` +
    "Continue from where we left off without re-asking the user.";
  return [{ role: "user", content: continuation }];
}

function backoffDelay(attempt: number): number {
  /** Exponential backoff with jitter: base * 2^attempt + random(0, 1). */
  const delay = Math.min(BACKOFF_BASE_DELAY * Math.pow(2, attempt), BACKOFF_MAX_DELAY);
  const jitter = Math.random();
  return delay + jitter;
}

function sleep(seconds: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, seconds * 1000));
}

// -- Tool implementations --
function safePath(p: string): string {
  const resolved = path.resolve(WORKDIR, p);
  if (!resolved.startsWith(WORKDIR + path.sep) && resolved !== WORKDIR)
    throw new Error(`Path escapes workspace: ${p}`);
  return resolved;
}

function runBash(command: string): string {
  const dangerous = ["rm -rf /", "sudo", "shutdown", "reboot", "> /dev/"];
  if (dangerous.some((d) => command.includes(d))) return "Error: Dangerous command blocked";
  try {
    const out = execSync(command, { cwd: WORKDIR, timeout: 120000, encoding: "utf-8", stdio: ["pipe","pipe","pipe"] });
    return out.trim().slice(0, 50000) || "(no output)";
  } catch (e: any) {
    if (e.signal === "SIGTERM") return "Error: Timeout (120s)";
    return (((e.stdout || "") + (e.stderr || "")).trim()).slice(0, 50000) || `Error: ${e.message}`;
  }
}

function runRead(p: string, limit?: number): string {
  try {
    const lines = fs.readFileSync(safePath(p), "utf-8").split("\n");
    const result = limit && limit < lines.length ? [...lines.slice(0, limit), `... (${lines.length - limit} more)`] : lines;
    return result.join("\n").slice(0, 50000);
  } catch (e: any) { return `Error: ${e.message}`; }
}

function runWrite(p: string, content: string): string {
  try {
    const fp = safePath(p);
    fs.mkdirSync(path.dirname(fp), { recursive: true });
    fs.writeFileSync(fp, content, "utf-8");
    return `Wrote ${content.length} bytes`;
  } catch (e: any) { return `Error: ${e.message}`; }
}

function runEdit(p: string, oldText: string, newText: string): string {
  try {
    const fp = safePath(p);
    const content = fs.readFileSync(fp, "utf-8");
    if (!content.includes(oldText)) return `Error: Text not found in ${p}`;
    fs.writeFileSync(fp, content.replace(oldText, newText), "utf-8");
    return `Edited ${p}`;
  } catch (e: any) { return `Error: ${e.message}`; }
}

const TOOL_HANDLERS: Record<string, (kw: Record<string, any>) => string> = {
  bash:       (kw) => runBash(kw.command),
  read_file:  (kw) => runRead(kw.path, kw.limit),
  write_file: (kw) => runWrite(kw.path, kw.content),
  edit_file:  (kw) => runEdit(kw.path, kw.old_text, kw.new_text),
};

const TOOLS: Anthropic.Tool[] = [
  { name: "bash", description: "Run a shell command.",
    input_schema: { type: "object", properties: { command: { type: "string" } }, required: ["command"] } },
  { name: "read_file", description: "Read file contents.",
    input_schema: { type: "object", properties: { path: { type: "string" }, limit: { type: "integer" } }, required: ["path"] } },
  { name: "write_file", description: "Write content to file.",
    input_schema: { type: "object", properties: { path: { type: "string" }, content: { type: "string" } }, required: ["path", "content"] } },
  { name: "edit_file", description: "Replace exact text in file.",
    input_schema: { type: "object", properties: { path: { type: "string" }, old_text: { type: "string" }, new_text: { type: "string" } }, required: ["path", "old_text", "new_text"] } },
];

const SYSTEM = `You are a coding agent at ${WORKDIR}. Use tools to solve tasks.`;

/**
 * Error-recovering agent loop with three paths:
 *
 * 1. continue after max_tokens
 * 2. compact after prompt-too-long
 * 3. back off after transient transport failure
 */
async function agentLoop(messages: Anthropic.MessageParam[]): Promise<void> {
  let maxOutputRecoveryCount = 0;

  while (true) {
    // -- Attempt the API call with connection retry --
    let response: Anthropic.Message | null = null;
    for (let attempt = 0; attempt <= MAX_RECOVERY_ATTEMPTS; attempt++) {
      try {
        response = await client.messages.create({
          model: MODEL, system: SYSTEM, messages, tools: TOOLS, max_tokens: 8000,
        });
        break; // success

      } catch (e: any) {
        const errBody = String(e).toLowerCase();

        // Strategy 2: prompt_too_long -> compact and retry
        if (errBody.includes("overlong_prompt") || (errBody.includes("prompt") && errBody.includes("long"))) {
          console.log(`[Recovery] Prompt too long. Compacting... (attempt ${attempt + 1})`);
          const compacted = await autoCompact(messages);
          messages.splice(0, messages.length, ...compacted);
          continue;
        }

        // Strategy 3: connection/rate errors -> backoff
        if (attempt < MAX_RECOVERY_ATTEMPTS) {
          const delay = backoffDelay(attempt);
          console.log(`[Recovery] API error: ${e.message}. Retrying in ${delay.toFixed(1)}s (attempt ${attempt + 1}/${MAX_RECOVERY_ATTEMPTS})`);
          await sleep(delay);
          continue;
        }

        // All retries exhausted
        console.log(`[Error] API call failed after ${MAX_RECOVERY_ATTEMPTS} retries: ${e.message}`);
        return;
      }
    }

    if (!response) { console.log("[Error] No response received."); return; }

    messages.push({ role: "assistant", content: response.content });

    // -- Strategy 1: max_tokens recovery --
    if (response.stop_reason === "max_tokens") {
      maxOutputRecoveryCount++;
      if (maxOutputRecoveryCount <= MAX_RECOVERY_ATTEMPTS) {
        console.log(`[Recovery] max_tokens hit (${maxOutputRecoveryCount}/${MAX_RECOVERY_ATTEMPTS}). Injecting continuation...`);
        messages.push({ role: "user", content: CONTINUATION_MESSAGE });
        continue; // retry the loop
      } else {
        console.log(`[Error] max_tokens recovery exhausted (${MAX_RECOVERY_ATTEMPTS} attempts). Stopping.`);
        return;
      }
    }

    // Reset max_tokens counter on successful non-max_tokens response
    maxOutputRecoveryCount = 0;

    // -- Normal end_turn: no tool use requested --
    if (response.stop_reason !== "tool_use") return;

    // -- Process tool calls --
    const results: Anthropic.ToolResultBlockParam[] = [];
    for (const block of response.content) {
      if (block.type !== "tool_use") continue;
      const handler = TOOL_HANDLERS[block.name];
      let output: string;
      try {
        output = handler ? handler(block.input as Record<string, any>) : `Unknown: ${block.name}`;
      } catch (e: any) { output = `Error: ${e.message}`; }
      console.log(`> ${block.name}: ${String(output).slice(0, 200)}`);
      results.push({ type: "tool_result", tool_use_id: block.id, content: String(output) });
    }
    messages.push({ role: "user", content: results });

    // Check if we should auto-compact (proactive, not just reactive)
    if (estimateTokens(messages) > TOKEN_THRESHOLD) {
      console.log("[Recovery] Token estimate exceeds threshold. Auto-compacting...");
      const compacted = await autoCompact(messages);
      messages.splice(0, messages.length, ...compacted);
    }
  }
}

async function main() {
  console.log("[Error recovery enabled: max_tokens / prompt_too_long / connection backoff]");
  const rl = readline.createInterface({ input: process.stdin, output: process.stdout, prompt: "\x1b[36ms11 >> \x1b[0m" });
  const history: Anthropic.MessageParam[] = [];
  rl.prompt();
  rl.on("line", async (query) => {
    rl.pause();
    if (!query.trim() || ["q", "exit"].includes(query.trim().toLowerCase())) { rl.close(); return; }
    history.push({ role: "user", content: query });
    await agentLoop(history);
    const last = history[history.length - 1];
    if (Array.isArray(last.content)) {
      for (const b of last.content) {
        if (typeof b === "object" && b !== null && (b as any).type === "text") console.log((b as any).text);
      }
    }
    console.log();
    rl.resume(); rl.prompt();
  });
  rl.on("close", () => process.exit(0));
}

main().catch(console.error);

// Harness: persistent tasks -- goals that outlive any single conversation.
/**
 * s12_task_system.ts - Tasks
 *
 * Tasks persist as JSON files in .tasks/ so they survive context compression.
 * Each task carries a small dependency graph:
 *
 * - blockedBy: what must finish first
 * - blocks: what this task unlocks later
 *
 * Key idea: task state survives compression because it lives on disk, not only
 * inside the conversation.
 * These are durable work-graph tasks, not transient runtime execution slots.
 */

import Anthropic from "@anthropic-ai/sdk";
import * as readline from "readline";
import { execSync } from "child_process";
import * as fs from "fs";
import * as path from "path";
import "dotenv/config";

if (process.env.ANTHROPIC_BASE_URL) {
  delete process.env.ANTHROPIC_AUTH_TOKEN;
}

const WORKDIR = process.cwd();
const client = new Anthropic({ baseURL: process.env.ANTHROPIC_BASE_URL });
const MODEL = process.env.MODEL_ID!;
const TASKS_DIR = path.join(WORKDIR, ".tasks");

const SYSTEM = `You are a coding agent at ${WORKDIR}. Use task tools to plan and track work.`;

type TaskStatus = "pending" | "in_progress" | "completed" | "deleted";
const STATUS_MARKER: Record<TaskStatus, string> = {
  pending: "[ ]", in_progress: "[>]", completed: "[x]", deleted: "[-]",
};

interface TaskRecord {
  id: number;
  subject: string;
  description: string;
  status: TaskStatus;
  blockedBy: number[];
  blocks: number[];
  owner: string;
}

/**
 * Persistent TaskRecord store.
 *
 * Think "work graph on disk", not "currently running worker".
 */
class TaskManager {
  private dir: string;
  private nextId: number;

  constructor(tasksDir: string) {
    this.dir = tasksDir;
    fs.mkdirSync(this.dir, { recursive: true });
    this.nextId = this._maxId() + 1;
  }

  private _maxId(): number {
    const ids = fs.readdirSync(this.dir)
      .filter((f) => /^task_\d+\.json$/.test(f))
      .map((f) => parseInt(f.split("_")[1]));
    return ids.length > 0 ? Math.max(...ids) : 0;
  }

  private _load(taskId: number): TaskRecord {
    const p = path.join(this.dir, `task_${taskId}.json`);
    if (!fs.existsSync(p)) throw new Error(`Task ${taskId} not found`);
    return JSON.parse(fs.readFileSync(p, "utf-8")) as TaskRecord;
  }

  private _save(task: TaskRecord): void {
    fs.writeFileSync(path.join(this.dir, `task_${task.id}.json`), JSON.stringify(task, null, 2), "utf-8");
  }

  create(subject: string, description = ""): string {
    const task: TaskRecord = {
      id: this.nextId++, subject, description,
      status: "pending", blockedBy: [], blocks: [], owner: "",
    };
    this._save(task);
    return JSON.stringify(task, null, 2);
  }

  get(taskId: number): string {
    return JSON.stringify(this._load(taskId), null, 2);
  }

  update(taskId: number, status?: TaskStatus, owner?: string, addBlockedBy?: number[], addBlocks?: number[]): string {
    const task = this._load(taskId);
    if (owner !== undefined) task.owner = owner;
    if (status) {
      if (!["pending", "in_progress", "completed", "deleted"].includes(status))
        throw new Error(`Invalid status: ${status}`);
      task.status = status;
      if (status === "completed") this._clearDependency(taskId);
    }
    if (addBlockedBy) task.blockedBy = [...new Set([...task.blockedBy, ...addBlockedBy])];
    if (addBlocks) {
      task.blocks = [...new Set([...task.blocks, ...addBlocks])];
      for (const blockedId of addBlocks) {
        try {
          const blocked = this._load(blockedId);
          if (!blocked.blockedBy.includes(taskId)) {
            blocked.blockedBy.push(taskId);
            this._save(blocked);
          }
        } catch {}
      }
    }
    this._save(task);
    return JSON.stringify(task, null, 2);
  }

  private _clearDependency(completedId: number): void {
    for (const file of fs.readdirSync(this.dir).filter((f) => /^task_\d+\.json$/.test(f))) {
      const task: TaskRecord = JSON.parse(fs.readFileSync(path.join(this.dir, file), "utf-8"));
      if (task.blockedBy.includes(completedId)) {
        task.blockedBy = task.blockedBy.filter((id) => id !== completedId);
        this._save(task);
      }
    }
  }

  listAll(): string {
    const files = fs.readdirSync(this.dir).filter((f) => /^task_\d+\.json$/.test(f)).sort();
    if (!files.length) return "No tasks.";
    const lines = files.map((file) => {
      const t: TaskRecord = JSON.parse(fs.readFileSync(path.join(this.dir, file), "utf-8"));
      const marker = STATUS_MARKER[t.status] ?? "[?]";
      const blocked = t.blockedBy.length ? ` (blocked by: [${t.blockedBy}])` : "";
      const owner = t.owner ? ` owner=${t.owner}` : "";
      return `${marker} #${t.id}: ${t.subject}${owner}${blocked}`;
    });
    return lines.join("\n");
  }
}

const TASKS = new TaskManager(TASKS_DIR);

// -- Base tool implementations --
function safePath(p: string): string {
  const resolved = path.resolve(WORKDIR, p);
  if (!resolved.startsWith(WORKDIR + path.sep) && resolved !== WORKDIR)
    throw new Error(`Path escapes workspace: ${p}`);
  return resolved;
}

function runBash(command: string): string {
  const dangerous = ["rm -rf /", "sudo", "shutdown", "reboot", "> /dev/"];
  if (dangerous.some((d) => command.includes(d))) return "Error: Dangerous command blocked";
  try {
    const out = execSync(command, { cwd: WORKDIR, timeout: 120000, encoding: "utf-8", stdio: ["pipe","pipe","pipe"] });
    return out.trim().slice(0, 50000) || "(no output)";
  } catch (e: any) {
    if (e.signal === "SIGTERM") return "Error: Timeout (120s)";
    return (((e.stdout || "") + (e.stderr || "")).trim()).slice(0, 50000) || `Error: ${e.message}`;
  }
}

function runRead(p: string, limit?: number): string {
  try {
    const lines = fs.readFileSync(safePath(p), "utf-8").split("\n");
    const result = limit && limit < lines.length ? [...lines.slice(0, limit), `... (${lines.length - limit} more)`] : lines;
    return result.join("\n").slice(0, 50000);
  } catch (e: any) { return `Error: ${e.message}`; }
}

function runWrite(p: string, content: string): string {
  try {
    const fp = safePath(p);
    fs.mkdirSync(path.dirname(fp), { recursive: true });
    fs.writeFileSync(fp, content, "utf-8");
    return `Wrote ${content.length} bytes`;
  } catch (e: any) { return `Error: ${e.message}`; }
}

function runEdit(p: string, oldText: string, newText: string): string {
  try {
    const fp = safePath(p);
    const c = fs.readFileSync(fp, "utf-8");
    if (!c.includes(oldText)) return `Error: Text not found in ${p}`;
    fs.writeFileSync(fp, c.replace(oldText, newText), "utf-8");
    return `Edited ${p}`;
  } catch (e: any) { return `Error: ${e.message}`; }
}

const TOOL_HANDLERS: Record<string, (kw: Record<string, any>) => string> = {
  bash:         (kw) => runBash(kw.command),
  read_file:    (kw) => runRead(kw.path, kw.limit),
  write_file:   (kw) => runWrite(kw.path, kw.content),
  edit_file:    (kw) => runEdit(kw.path, kw.old_text, kw.new_text),
  task_create:  (kw) => TASKS.create(kw.subject, kw.description ?? ""),
  task_update:  (kw) => TASKS.update(kw.task_id, kw.status, kw.owner, kw.addBlockedBy, kw.addBlocks),
  task_list:    (_kw) => TASKS.listAll(),
  task_get:     (kw) => TASKS.get(kw.task_id),
};

const TOOLS: Anthropic.Tool[] = [
  { name: "bash", description: "Run a shell command.",
    input_schema: { type: "object", properties: { command: { type: "string" } }, required: ["command"] } },
  { name: "read_file", description: "Read file contents.",
    input_schema: { type: "object", properties: { path: { type: "string" }, limit: { type: "integer" } }, required: ["path"] } },
  { name: "write_file", description: "Write content to file.",
    input_schema: { type: "object", properties: { path: { type: "string" }, content: { type: "string" } }, required: ["path", "content"] } },
  { name: "edit_file", description: "Replace exact text in file.",
    input_schema: { type: "object", properties: { path: { type: "string" }, old_text: { type: "string" }, new_text: { type: "string" } }, required: ["path", "old_text", "new_text"] } },
  { name: "task_create", description: "Create a new task.",
    input_schema: { type: "object", properties: { subject: { type: "string" }, description: { type: "string" } }, required: ["subject"] } },
  { name: "task_update", description: "Update a task's status, owner, or dependencies.",
    input_schema: { type: "object", properties: {
